export const specSources: Record<string, { yaml: string; data: unknown }> = {
  "add-to-cart-rate": { yaml: "id: add-to-cart-rate\nname: Add-to-cart rate\naliases:\n  - ATC rate\n  - Add to cart conversion rate\n  - Cart addition rate\nfamily: conversion\ncatalog_id: add_to_cart_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.\n  formula: Sessions that added to cart ÷ sessions that viewed a product\n\nevents:\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n      - name: price\n        description: Unit price at the time of adding, before discounts.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\ndenominator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\n\nnoise:\n  type: binomial\n  min_denominator: 300\n  volume_unit: product-viewing sessions a week\n  typical: 0.1\n  reference_volumes: [1000, 5000, 25000, 100000]\n\nexample:\n  business: store\n  level: 0.108\n  volume: 372000\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme update or a new cart drawer app stop product_added firing on some buttons?\n      yes: Orders and checkout starts hold while recorded adds fall, often from one template or device.\n    spiked:\n      check: Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?\n      yes: Adds per session jump while checkout starts don't follow.\n  - id: price-and-offers\n    label: Prices, sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, prices rise, or the free-shipping threshold move this week?\n      yes: Adds fall on the products whose price or offer changed, from the day it changed.\n    spiked:\n      check: Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?\n      yes: Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying.\n  - id: stock\n    label: Stock and sizes\n    dropped:\n      check: Did best sellers or common sizes go out of stock?\n      yes: Views hold on the top products while their adds fall to near zero.\n    spiked:\n      check: Did a best seller or a missing size come back in stock?\n      yes: Adds jump on the restocked products from the restock day while the rest hold.\n  - id: page-release\n    label: Product page changes\n    dropped:\n      check: Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?\n      yes: The drop starts on the release day across every traffic source.\n    spiked:\n      check: Did a release or test ship a clearer buy box, and is it the same for everyone?\n      yes: The rise starts on the release day; confirm the test isn't counting one add twice.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?\n      yes: Mobile falls while desktop holds, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release while the other holds.\n  - id: traffic-mix\n    label: Who is browsing\n    breakdown: utm_source\n    dropped:\n      check: Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?\n      yes: One source gains share of product views and adds far less often than the rest.\n    spiked:\n      check: Did a high-intent source grow, such as email or branded search?\n      yes: One source gains share of product views while each source's own rate holds.\n\ndiagnose_order: [tracking, price-and-offers, stock, page-release, device-split, traffic-mix]\n\nrelated: [product-view-rate, checkout-start-rate, cart-abandonment-rate, conversion-rate, aov]\n\nprose:\n  why_it_matters: >-\n    Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout\n    can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700\n    carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.\n  pitfalls:\n    - Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.\n    - Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.\n    - Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.\n    - Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"add-to-cart-rate","name":"Add-to-cart rate","aliases":["ATC rate","Add to cart conversion rate","Cart addition rate"],"family":"conversion","catalog_id":"add_to_cart_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed a product and added something to the cart, the store's clearest read on product pages.","formula":"Sessions that added to cart ÷ sessions that viewed a product"},"events":[{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."}]},{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."},{"name":"price","description":"Unit price at the time of adding, before discounts."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"denominator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"noise":{"type":"binomial","min_denominator":300,"volume_unit":"product-viewing sessions a week","typical":0.1,"reference_volumes":[1000,5000,25000,100000]},"example":{"business":"store","level":0.108,"volume":372000,"trend":0.02,"season":0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme update or a new cart drawer app stop product_added firing on some buttons?","yes":"Orders and checkout starts hold while recorded adds fall, often from one template or device."},"spiked":{"check":"Is product_added now firing on quantity changes, on both the drawer and the form, or on page load?","yes":"Adds per session jump while checkout starts don't follow."}},{"id":"price-and-offers","label":"Prices, sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, prices rise, or the free-shipping threshold move this week?","yes":"Adds fall on the products whose price or offer changed, from the day it changed."},"spiked":{"check":"Is a sale, a holiday or a new offer lifting adds, and do checkout starts follow?","yes":"Adds rise on discounted products; if checkout starts don't rise with them, shoppers are comparing, not buying."}},{"id":"stock","label":"Stock and sizes","dropped":{"check":"Did best sellers or common sizes go out of stock?","yes":"Views hold on the top products while their adds fall to near zero."},"spiked":{"check":"Did a best seller or a missing size come back in stock?","yes":"Adds jump on the restocked products from the restock day while the rest hold."}},{"id":"page-release","label":"Product page changes","dropped":{"check":"Did a release move the add-to-cart button, add a required option, slow the page or change photos or reviews?","yes":"The drop starts on the release day across every traffic source."},"spiked":{"check":"Did a release or test ship a clearer buy box, and is it the same for everyone?","yes":"The rise starts on the release day; confirm the test isn't counting one add twice."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on mobile only, for example a sticky add-to-cart bar that stopped showing?","yes":"Mobile falls while desktop holds, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release while the other holds."}},{"id":"traffic-mix","label":"Who is browsing","breakdown":"utm_source","dropped":{"check":"Did more browsers arrive from a low-intent source, such as broad paid social or a gift guide?","yes":"One source gains share of product views and adds far less often than the rest."},"spiked":{"check":"Did a high-intent source grow, such as email or branded search?","yes":"One source gains share of product views while each source's own rate holds."}}],"diagnose_order":["tracking","price-and-offers","stock","page-release","device-split","traffic-mix"],"related":["product-view-rate","checkout-start-rate","cart-abandonment-rate","conversion-rate","aov"],"prose":{"why_it_matters":"Add-to-cart rate is where price, photos, reviews and stock show up first, before checkout can help or hurt. On 372,000 product-viewing sessions a week, one point is about 3,700 carts, and with a third of carts becoming orders that is roughly 1,200 orders a week.","pitfalls":["Shopify's dashboard divides adds by all sessions, not product-viewing sessions, so the same store reads about 6.7% there and 10.8% here. Compare like with like.","Quick-add buttons on collection pages and upsells add to cart without a product view, so heavy quick-add stores see this rate drift up with no change in product pages.","Counting add events instead of sessions rewards quantity buttons; three taps on plus are one shopper. This spec counts sessions.","Adding to cart is cheap intent. A rise that checkout starts don't follow is usually a promotion, a tracking change or price comparison, not better product pages."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "aov": { yaml: "id: aov\nname: Average order value\naliases:\n  - Average order value\n  - Average basket value\n  - Average transaction value\n  - Average purchase revenue\nfamily: revenue\ncatalog_id: aov\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The average paid order's value after discounts, before tax, shipping and refunds.\n  formula: Order revenue after discounts ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 90\n\nexample:\n  business: store\n  level: 97\n  volume: 13300\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?\n      yes: A cluster of orders at or near $0 appears from one day.\n    spiked:\n      check: Did order totals start including tax or shipping, or did one currency arrive unconverted?\n      yes: Totals jump for one country or channel from one day while subtotals hold.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Is a sale running, when discounts and cheaper gift items pull the average down?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting week, or did a sale that lowered the average just end?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: discounts\n    label: Discounts\n    metric: discount-rate\n    dropped:\n      check: Did the share of sales given away in discounts rise?\n      yes: Discount rate rises while items per order hold, and the average falls by about the extra discount.\n    spiked:\n      check: Did a promotion end, so orders carry less discount?\n      yes: Discount rate falls by about as much as the average rises.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?\n      yes: Units per order fall while the price per unit holds.\n    spiked:\n      check: Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?\n      yes: The price per unit falls while items per order hold.\n    spiked:\n      check: Did prices rise, a premium product launch, or did a handful of very large orders land?\n      yes: The price per unit rises, or the ten largest orders explain most of the jump.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders, which are usually smaller, take a larger share of orders?\n      yes: Each group's average holds and only the mix moved.\n    spiked:\n      check: Did repeat customers take a larger share, or did first orders grow in size?\n      yes: The mix moved toward repeat orders, or first orders' average rose on its own.\n\ndiagnose_order: [tracking, calendar, discounts, basket-size, price-and-mix, first-orders]\n\nrelated: [net-revenue, orders, units-per-order, discount-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\".\n    It moves with prices, discounts, basket size and who is buying, not with traffic. At\n    Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 135\n    more orders.\n  pitfalls:\n    - Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.\n    - Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.\n    - Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.\n    - A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"aov","name":"Average order value","aliases":["Average order value","Average basket value","Average transaction value","Average purchase revenue"],"family":"revenue","catalog_id":"aov","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The average paid order's value after discounts, before tax, shipping and refunds.","formula":"Order revenue after discounts ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":90},"example":{"business":"store","level":97,"volume":13300,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did $0 orders, such as replacements, gifts or influencer seeding, start recording as paid orders?","yes":"A cluster of orders at or near $0 appears from one day."},"spiked":{"check":"Did order totals start including tax or shipping, or did one currency arrive unconverted?","yes":"Totals jump for one country or channel from one day while subtotals hold."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Is a sale running, when discounts and cheaper gift items pull the average down?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting week, or did a sale that lowered the average just end?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"discounts","label":"Discounts","metric":"discount-rate","dropped":{"check":"Did the share of sales given away in discounts rise?","yes":"Discount rate rises while items per order hold, and the average falls by about the extra discount."},"spiked":{"check":"Did a promotion end, so orders carry less discount?","yes":"Discount rate falls by about as much as the average rises."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did orders carry fewer items, after a bundle ended or the free-shipping threshold fell?","yes":"Units per order fall while the price per unit holds."},"spiked":{"check":"Did a bundle, a multi-buy offer or a higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did sales shift toward cheaper products, such as a low-priced launch or an entry product in ads?","yes":"The price per unit falls while items per order hold."},"spiked":{"check":"Did prices rise, a premium product launch, or did a handful of very large orders land?","yes":"The price per unit rises, or the ten largest orders explain most of the jump."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders, which are usually smaller, take a larger share of orders?","yes":"Each group's average holds and only the mix moved."},"spiked":{"check":"Did repeat customers take a larger share, or did first orders grow in size?","yes":"The mix moved toward repeat orders, or first orders' average rose on its own."}}],"diagnose_order":["tracking","calendar","discounts","basket-size","price-and-mix","first-orders"],"related":["net-revenue","orders","units-per-order","discount-rate","revenue-per-session"],"prose":{"why_it_matters":"Revenue is orders × AOV, so AOV separates \"fewer people bought\" from \"people bought less\". It moves with prices, discounts, basket size and who is buying, not with traffic. At Northwind, $1 of AOV across 13,300 orders is $13,300 a week, the same revenue as about 135 more orders.","pitfalls":["Averages follow large orders. A few wholesale or bulk orders can lift a small store's AOV 10% in a week; check the median order beside it.","Dividing net revenue after refunds by orders makes AOV move with refunds on earlier weeks' orders. This spec divides the week's own order revenue by its order count and reads refunds in refund rate.","Including tax and shipping makes AOV move with tax rules, destinations and carrier prices. Keep both out.","A promotion that lowers AOV can still raise revenue. Judge AOV with orders beside it, never alone."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "cart-abandonment-rate": { yaml: "id: cart-abandonment-rate\nname: Cart abandonment rate\naliases:\n  - Cart abandonment\n  - Shopping cart abandonment rate\n  - Abandoned cart rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.\n  formula: 1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n      - name: quantity\n        description: Units added in this action.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\nsubtract:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.7\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.67\n  volume: 40000\n  trend: -0.03\n  season: -0.5\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?\n      yes: Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold.\n    spiked:\n      check: Did an add-to-cart event start firing twice, or did order events stop being recorded?\n      yes: Carts rise without checkout starts following, or recorded orders fall below the processor's count.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is this a sale week, when carts that were parked the week before finally convert?\n      yes: Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is it the week before a sale, when shoppers fill carts and wait for the discount?\n      yes: Carts rise while orders hold, and the same week last year shows the same rise.\n  - id: cart-to-checkout\n    label: Cart to checkout\n    metric: checkout-start-rate\n    dropped:\n      check: Did more carts move on to checkout, after a cart page or shipping message change?\n      yes: Checkout start rate rises by about as much as abandonment falls.\n    spiked:\n      check: Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?\n      yes: Checkout start rate falls while checkout completion holds.\n  - id: checkout-completion\n    label: Checkout completion\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts finish, after a checkout fix or a payment method launch?\n      yes: Checkout conversion rises while checkout starts hold.\n    spiked:\n      check: Did more checkouts fail at shipping, account creation or payment?\n      yes: Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it.\n  - id: extra-costs\n    label: Shipping, tax and fees\n    dropped:\n      check: Did a free-shipping offer, a lower threshold or a clearer delivery date go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n    spiked:\n      check: Did shipping prices, thresholds, duties or fees shown late in checkout change?\n      yes: Exits concentrate on the shipping step, starting the day the change shipped.\n  - id: device-mix\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Did desktop take a larger share of carts, or did mobile abandonment fall?\n      yes: Each device's rate holds and the mix moved, or mobile falls after a release.\n    spiked:\n      check: Did mobile take a larger share of carts, or did mobile abandonment rise on its own?\n      yes: Each device's rate holds and only the mix moved, or mobile rises while desktop holds.\n\ndiagnose_order: [tracking, calendar, cart-to-checkout, checkout-completion, extra-costs, device-mix]\n\nrelated: [checkout-start-rate, checkout-conversion, add-to-cart-rate, conversion-rate, payment-success-rate]\n\nprose:\n  why_it_matters: >-\n    About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's\n    average of dozens of studies, and most of them were never going to buy. The part a store\n    can win back is the rest: extra costs shown late, forced accounts, slow delivery and\n    checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of\n    abandonment is about 400 orders.\n  pitfalls:\n    - Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is the most common mistake with this number.\n    - This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.\n    - Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.\n    - Mobile carts are abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.\n    - The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"cart-abandonment-rate","name":"Cart abandonment rate","aliases":["Cart abandonment","Shopping cart abandonment rate","Abandoned cart rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of shopping carts that never become a paid order, by Baymard's definition of one minus orders over carts.","formula":"1 − sessions with a paid order ÷ sessions that added to cart, both counted in the same week"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."},{"name":"quantity","description":"Units added in this action."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"subtract":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.7,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.67,"volume":40000,"trend":-0.03,"season":-0.5},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Is a duplicate order event, or a missing add-to-cart event on one platform, shrinking the gap?","yes":"Orders recorded exceed orders in the payment processor, or adds fall on one device while orders hold."},"spiked":{"check":"Did an add-to-cart event start firing twice, or did order events stop being recorded?","yes":"Carts rise without checkout starts following, or recorded orders fall below the processor's count."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is this a sale week, when carts that were parked the week before finally convert?","yes":"Orders rise faster than carts, and the same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is it the week before a sale, when shoppers fill carts and wait for the discount?","yes":"Carts rise while orders hold, and the same week last year shows the same rise."}},{"id":"cart-to-checkout","label":"Cart to checkout","metric":"checkout-start-rate","dropped":{"check":"Did more carts move on to checkout, after a cart page or shipping message change?","yes":"Checkout start rate rises by about as much as abandonment falls."},"spiked":{"check":"Did fewer carts reach checkout, from a cart page change, a surprise cost or a broken button?","yes":"Checkout start rate falls while checkout completion holds."}},{"id":"checkout-completion","label":"Checkout completion","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts finish, after a checkout fix or a payment method launch?","yes":"Checkout conversion rises while checkout starts hold."},"spiked":{"check":"Did more checkouts fail at shipping, account creation or payment?","yes":"Checkout conversion falls while checkout starts hold; one step or one payment method explains most of it."}},{"id":"extra-costs","label":"Shipping, tax and fees","dropped":{"check":"Did a free-shipping offer, a lower threshold or a clearer delivery date go live?","yes":"Fewer exits at the shipping step from the day it launched."},"spiked":{"check":"Did shipping prices, thresholds, duties or fees shown late in checkout change?","yes":"Exits concentrate on the shipping step, starting the day the change shipped."}},{"id":"device-mix","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Did desktop take a larger share of carts, or did mobile abandonment fall?","yes":"Each device's rate holds and the mix moved, or mobile falls after a release."},"spiked":{"check":"Did mobile take a larger share of carts, or did mobile abandonment rise on its own?","yes":"Each device's rate holds and only the mix moved, or mobile rises while desktop holds."}}],"diagnose_order":["tracking","calendar","cart-to-checkout","checkout-completion","extra-costs","device-mix"],"related":["checkout-start-rate","checkout-conversion","add-to-cart-rate","conversion-rate","payment-success-rate"],"prose":{"why_it_matters":"About 70 of every 100 carts are abandoned on the average store, by Baymard Institute's average of dozens of studies, and most of them were never going to buy. The part a store can win back is the rest: extra costs shown late, forced accounts, slow delivery and checkouts that ask too much. At Northwind, with 40,000 carts a week, one point of abandonment is about 400 orders.","pitfalls":["Cart abandonment is not checkout abandonment. One minus checkout conversion counts only shoppers who started checkout and reads far lower; comparing either with the other's benchmark is the most common mistake with this number.","This spec compares carts and orders in aggregate, as Baymard does, so a shopper who adds on Monday and buys on Thursday in a new session counts once on each side and nets out.","Orders placed without an add-to-cart, such as buy-now buttons, reorder links and subscription renewals, pull the rate down. Send product_added for them or exclude them.","Mobile carts are abandoned more often than desktop carts, so a rise in mobile share lifts the rate with no change in the store. Split by device before blaming checkout.","The week before a big sale people fill carts and wait. Compare that week with the same week last year, not the week before."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-conversion": { yaml: "id: checkout-conversion\nname: Checkout conversion\naliases:\n  - Checkout completion rate\n  - Checkout conversion rate\n  - Checkout success rate\nfamily: conversion\ncatalog_id: checkout_completion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of started checkouts that become a paid order in the same week.\n  formula: Paid orders ÷ checkouts started\n\nevents:\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: checkouts started a week\n  typical: 0.62\n\nexample:\n  business: store\n  level: 0.63\n  volume: 20900\n  trend: 0.02\n  season: 0.5\n\ndrivers:\n  - id: payment-failures\n    label: Payment failures\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did payment success fall, and is it one gateway, card brand or wallet?\n      yes: Declines or errors rise for one processor or method while the others hold.\n    spiked:\n      check: Did a payment problem from the week before just clear?\n      yes: Payment success returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls several points while desktop is flat, which points at a release or layout bug.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n  - id: shipping-and-fees\n    label: Shipping cost and delivery dates\n    dropped:\n      check: Did shipping prices, thresholds or delivery promises change this week?\n      yes: Drop-off concentrates on the shipping step, starting the day the change shipped.\n    spiked:\n      check: Did a free-shipping threshold or faster delivery promise go live?\n      yes: Fewer exits at the shipping step from the day it launched.\n  - id: discount-codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    dropped:\n      check: Did a popular code expire, or did a coupon site start listing codes that fail?\n      yes: More sessions enter a code field and leave after an invalid-code message.\n    spiked:\n      check: Is a sale or a leaked code pushing people through?\n      yes: Code usage jumps and order value per order falls.\n  - id: traffic-mix\n    label: Who reached checkout\n    metric: checkout-start-rate\n    breakdown: utm_source\n    dropped:\n      check: Did more low-intent visitors reach checkout, for example from a new campaign?\n      yes: Checkout starts rise from one source whose completion is far below the rest.\n    spiked:\n      check: Did fewer but more committed visitors reach checkout?\n      yes: Checkout starts fall while completion rises; orders barely move.\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did an event, consent banner or tag manager change stop orders being recorded?\n      yes: Orders in the payment processor hold steady while recorded orders fall.\n    spiked:\n      check: Is a duplicate order event or a missing checkout event inflating the rate?\n      yes: Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform.\n\ndiagnose_order: [tracking, payment-failures, device-split, shipping-and-fees, discount-codes, traffic-mix]\n\nrelated: [checkout-start-rate, payment-success-rate, conversion-rate, cart-abandonment-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout is the last step a store controls, so a change here is rarely about demand and\n    almost always about something the team shipped, a partner that broke, or a price the\n    shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is\n    about 100 lost orders, every week, until someone finds it.\n  pitfalls:\n    - Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.\n    - Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.\n    - Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.\n    - Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-conversion","name":"Checkout conversion","aliases":["Checkout completion rate","Checkout conversion rate","Checkout success rate"],"family":"conversion","catalog_id":"checkout_completion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of started checkouts that become a paid order in the same week.","formula":"Paid orders ÷ checkouts started"},"events":[{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"checkouts started a week","typical":0.62},"example":{"business":"store","level":0.63,"volume":20900,"trend":0.02,"season":0.5},"drivers":[{"id":"payment-failures","label":"Payment failures","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did payment success fall, and is it one gateway, card brand or wallet?","yes":"Declines or errors rise for one processor or method while the others hold."},"spiked":{"check":"Did a payment problem from the week before just clear?","yes":"Payment success returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls several points while desktop is flat, which points at a release or layout bug."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}},{"id":"shipping-and-fees","label":"Shipping cost and delivery dates","dropped":{"check":"Did shipping prices, thresholds or delivery promises change this week?","yes":"Drop-off concentrates on the shipping step, starting the day the change shipped."},"spiked":{"check":"Did a free-shipping threshold or faster delivery promise go live?","yes":"Fewer exits at the shipping step from the day it launched."}},{"id":"discount-codes","label":"Discount codes","metric":"promo-code-usage-rate","dropped":{"check":"Did a popular code expire, or did a coupon site start listing codes that fail?","yes":"More sessions enter a code field and leave after an invalid-code message."},"spiked":{"check":"Is a sale or a leaked code pushing people through?","yes":"Code usage jumps and order value per order falls."}},{"id":"traffic-mix","label":"Who reached checkout","metric":"checkout-start-rate","breakdown":"utm_source","dropped":{"check":"Did more low-intent visitors reach checkout, for example from a new campaign?","yes":"Checkout starts rise from one source whose completion is far below the rest."},"spiked":{"check":"Did fewer but more committed visitors reach checkout?","yes":"Checkout starts fall while completion rises; orders barely move."}},{"id":"tracking","label":"Tracking change","dropped":{"check":"Did an event, consent banner or tag manager change stop orders being recorded?","yes":"Orders in the payment processor hold steady while recorded orders fall."},"spiked":{"check":"Is a duplicate order event or a missing checkout event inflating the rate?","yes":"Orders recorded exceed orders in the processor, or checkout starts drop to near zero on one platform."}}],"diagnose_order":["tracking","payment-failures","device-split","shipping-and-fees","discount-codes","traffic-mix"],"related":["checkout-start-rate","payment-success-rate","conversion-rate","cart-abandonment-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Checkout is the last step a store controls, so a change here is rarely about demand and almost always about something the team shipped, a partner that broke, or a price the shopper saw late. A one-point drop on a store that starts 10,000 checkouts a week is about 100 lost orders, every week, until someone finds it.","pitfalls":["Counting the thank-you page instead of a server-side order event double counts reloads and misses orders paid by redirect methods.","Mixing checkout attempts and sessions in one ratio. Pick one unit for both sides; this spec uses sessions.","Reading a week-over-week move without the volume. Below about 1,000 checkouts a week, a two-point swing is often chance.","Comparing Black Friday week with the week before. Intent is different; compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "checkout-start-rate": { yaml: "id: checkout-start-rate\nname: Checkout start rate\naliases:\n  - Checkout initiation rate\n  - Cart to checkout rate\n  - Reached checkout rate\nfamily: conversion\ncatalog_id: checkout_start_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.\n  formula: Sessions that started checkout ÷ sessions that added to cart\n\nevents:\n  - name: product_added\n    description: An item added to the cart from any button, confirmed by the cart, not the click.\n    also_called: [add_to_cart, Product Added, product_added_to_cart]\n    properties:\n      - name: product_id\n        description: The product added.\n  - name: checkout_started\n    description: The first checkout step rendered, before shipping or payment details.\n    also_called: [begin_checkout, Checkout Started, checkout_initiated]\n    properties:\n      - name: checkout_id\n        description: One id per checkout attempt, so reloads don't count twice.\n\nnumerator:\n  label: Sessions that started checkout\n  aggregate: unique_sessions\n  event: checkout_started\ndenominator:\n  label: Sessions that added to cart\n  aggregate: unique_sessions\n  event: product_added\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: carts a week\n  typical: 0.5\n  reference_volumes: [500, 2000, 10000, 40000]\n\nexample:\n  business: store\n  level: 0.52\n  volume: 40000\n  trend: 0.01\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?\n      yes: Orders hold while checkout starts fall, often for one wallet or one device.\n    spiked:\n      check: Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?\n      yes: Checkout starts rise while orders don't, or starts per session jump on a release day.\n  - id: calendar\n    label: Sale calendar\n    feed: shopping\n    dropped:\n      check: Is it the week before a sale, when shoppers park items in the cart and wait?\n      yes: Carts rise while checkout starts hold, and the same week last year shows the same dip.\n    spiked:\n      check: Is this a sale or holiday week, when parked carts move to checkout?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: cart-intent\n    label: How easily people add to cart\n    metric: add-to-cart-rate\n    dropped:\n      check: Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?\n      yes: Carts rise while checkout starts hold, so the rate falls with no loss of orders.\n    spiked:\n      check: Did add-to-cart rate fall, leaving only the most committed carts?\n      yes: Carts fall while checkout starts hold; check orders before celebrating.\n  - id: cart-costs\n    label: Costs shown in the cart\n    dropped:\n      check: Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?\n      yes: The drop starts on the day the cart message changed, on every device.\n    spiked:\n      check: Did a free-shipping offer or a lower threshold go live in the cart?\n      yes: The rise starts on the launch day and orders follow.\n  - id: express-checkout\n    label: Express and wallet buttons\n    dropped:\n      check: Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?\n      yes: Wallet checkouts fall while card checkouts hold, from the day of a theme or app change.\n    spiked:\n      check: Did express buttons start sending shoppers from product pages straight to checkout?\n      yes: Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, such as a checkout button hidden on small screens?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, cart-intent, cart-costs, express-checkout, device-split]\n\nrelated: [add-to-cart-rate, checkout-conversion, cart-abandonment-rate, conversion-rate, promo-code-usage-rate]\n\nprose:\n  why_it_matters: >-\n    Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise\n    costs, a cart that buries its button or a missing wallet show up, well before payment. At\n    Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.\n  pitfalls:\n    - Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.\n    - Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.\n    - Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.\n    - A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"checkout-start-rate","name":"Checkout start rate","aliases":["Checkout initiation rate","Cart to checkout rate","Reached checkout rate"],"family":"conversion","catalog_id":"checkout_start_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions with a cart that went on to start checkout, the step where a cart becomes a decision to buy.","formula":"Sessions that started checkout ÷ sessions that added to cart"},"events":[{"name":"product_added","description":"An item added to the cart from any button, confirmed by the cart, not the click.","also_called":["add_to_cart","Product Added","product_added_to_cart"],"properties":[{"name":"product_id","description":"The product added."}]},{"name":"checkout_started","description":"The first checkout step rendered, before shipping or payment details.","also_called":["begin_checkout","Checkout Started","checkout_initiated"],"properties":[{"name":"checkout_id","description":"One id per checkout attempt, so reloads don't count twice."}]}],"numerator":{"label":"Sessions that started checkout","aggregate":"unique_sessions","event":"checkout_started"},"denominator":{"label":"Sessions that added to cart","aggregate":"unique_sessions","event":"product_added"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"carts a week","typical":0.5,"reference_volumes":[500,2000,10000,40000]},"example":{"business":"store","level":0.52,"volume":40000,"trend":0.01},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout app, domain or express-pay change stop checkout_started firing for some shoppers?","yes":"Orders hold while checkout starts fall, often for one wallet or one device."},"spiked":{"check":"Is checkout_started firing twice, or when the cart drawer opens rather than when checkout loads?","yes":"Checkout starts rise while orders don't, or starts per session jump on a release day."}},{"id":"calendar","label":"Sale calendar","feed":"shopping","dropped":{"check":"Is it the week before a sale, when shoppers park items in the cart and wait?","yes":"Carts rise while checkout starts hold, and the same week last year shows the same dip."},"spiked":{"check":"Is this a sale or holiday week, when parked carts move to checkout?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"cart-intent","label":"How easily people add to cart","metric":"add-to-cart-rate","dropped":{"check":"Did add-to-cart rate jump from looser intent, such as a quick-add launch or a free gift for adding?","yes":"Carts rise while checkout starts hold, so the rate falls with no loss of orders."},"spiked":{"check":"Did add-to-cart rate fall, leaving only the most committed carts?","yes":"Carts fall while checkout starts hold; check orders before celebrating."}},{"id":"cart-costs","label":"Costs shown in the cart","dropped":{"check":"Did the cart start showing shipping costs, a minimum order or a higher free-shipping threshold?","yes":"The drop starts on the day the cart message changed, on every device."},"spiked":{"check":"Did a free-shipping offer or a lower threshold go live in the cart?","yes":"The rise starts on the launch day and orders follow."}},{"id":"express-checkout","label":"Express and wallet buttons","dropped":{"check":"Did Shop Pay, Apple Pay or PayPal buttons disappear from the cart or move below the fold?","yes":"Wallet checkouts fall while card checkouts hold, from the day of a theme or app change."},"spiked":{"check":"Did express buttons start sending shoppers from product pages straight to checkout?","yes":"Sessions start checkout without an add-to-cart event, so the rate rises with no change in carts."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, such as a checkout button hidden on small screens?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","cart-intent","cart-costs","express-checkout","device-split"],"related":["add-to-cart-rate","checkout-conversion","cart-abandonment-rate","conversion-rate","promo-code-usage-rate"],"prose":{"why_it_matters":"Checkout start rate shows whether a cart turns into a decision to buy. It is where surprise costs, a cart that buries its button or a missing wallet show up, well before payment. At Northwind, with about 40,000 carts a week, one point is 400 checkouts and roughly 250 orders.","pitfalls":["Express buttons on product pages skip the cart, so those sessions start checkout without an add-to-cart and lift the rate. Track them as an add or read them separately.","Cart drawers make views of the cart page meaningless; this spec uses the add-to-cart and checkout events, never page views of /cart.","Counting checkout starts instead of sessions double counts shoppers who go back to edit the cart and start again. This spec counts sessions on both sides.","A rise in add-to-cart rate often lowers this rate with no harm done. Read the two together and judge them by orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "contribution-margin": { yaml: "id: contribution-margin\nname: Contribution margin\naliases:\n  - Contribution profit\n  - Contribution after marketing\n  - CM3\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.\n  formula: Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: ad_spend\n    description: Spend synced from each ad platform, one row per channel per day.\n    also_called: [ad insights, campaign cost data, cost import]\n    properties:\n      - name: channel\n        description: The platform or channel, such as meta, google or tiktok.\n      - name: spend\n        description: Spend for the day, in the store's currency.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nqueries:\n  hogql: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(timestamp) AS week,\n      sumIf(toFloat(properties.total), event = 'order_completed') - sumIf(toFloat(properties.amount), event = 'order_refunded') AS net_revenue,\n      sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n      sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend,\n      net_revenue - cost_of_goods - ad_spend AS value\n    FROM events\n    WHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH weekly AS (\n      SELECT\n        date_trunc('week', occurred_at)::date AS week,\n        coalesce(sum((properties->>'total')::numeric) FILTER (WHERE event_name = 'order_completed'), 0)\n          - coalesce(sum((properties->>'amount')::numeric) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n        coalesce(sum((properties->>'cost_of_goods')::numeric) FILTER (WHERE event_name = 'order_completed'), 0) AS cost_of_goods,\n        coalesce(sum((properties->>'spend')::numeric) FILTER (WHERE event_name = 'ad_spend'), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY 1\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n  bigquery: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH weekly AS (\n      SELECT\n        DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n        COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n          - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n        COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)), 0) AS cost_of_goods,\n        COALESCE(SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY week\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n  snowflake: |-\n    -- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    WITH weekly AS (\n      SELECT\n        DATE_TRUNC('week', occurred_at)::date AS week,\n        COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"total\"::float, NULL)), 0)\n          - COALESCE(SUM(IFF(event_name = 'order_refunded', properties:\"amount\"::float, NULL)), 0) AS net_revenue,\n        COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"cost_of_goods\"::float, NULL)), 0) AS cost_of_goods,\n        COALESCE(SUM(IFF(event_name = 'ad_spend', properties:\"spend\"::float, NULL)), 0) AS ad_spend\n      FROM events\n      WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY 1\n    )\n    SELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\n    FROM weekly\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 100000\n\nexample:\n  business: store\n  level: 291000\n  volume: 13300\n  trend: 0.15\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Spend and cost data\n    dropped:\n      check: Did ad spend sync twice for a platform, or did cost_of_goods change basis?\n      yes: One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date.\n    spiked:\n      check: Did an ad platform's spend sync fail, or did products start selling without a recorded cost?\n      yes: One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating.\n  - id: ad-spend\n    label: Ad spend\n    metric: ad-spend\n    feed: ad-platforms\n    dropped:\n      check: Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?\n      yes: Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin.\n    spiked:\n      check: Did spend fall, from a budget cut, a paused campaign or an ad account problem?\n      yes: Spend falls while revenue holds this week; watch whether new customers fall in the weeks after.\n  - id: net-revenue\n    label: Net revenue\n    metric: net-revenue\n    feed: shopping\n    dropped:\n      check: Did net revenue fall, from fewer orders, smaller orders or more refunds?\n      yes: Net revenue falls while spend and margin hold.\n    spiked:\n      check: Is this a sale or holiday week, or did revenue rise for a reason that will last?\n      yes: Net revenue rises while spend holds; the same week last year shows whether it's the calendar.\n  - id: gross-margin\n    label: Gross margin\n    metric: gross-margin\n    dropped:\n      check: Did discounts, product mix or unit costs lower gross margin?\n      yes: Gross margin falls while revenue and spend hold.\n    spiked:\n      check: Did a sale end or a price rise lift gross margin?\n      yes: Gross margin rises while revenue and spend hold.\n  - id: efficiency\n    label: Marketing efficiency\n    metric: mer\n    dropped:\n      check: Did each ad dollar bring in less revenue, from rising CPMs or tired creative?\n      yes: MER falls while spend holds.\n    spiked:\n      check: Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?\n      yes: MER rises while spend holds; check the calendar before crediting the ads.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds jump, after a big sale, a bad batch or a delivery problem?\n      yes: Refund rate rises while gross sales and spend hold.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refund rate returns to its usual level and margin recovers with it.\n\ndiagnose_order: [tracking, ad-spend, net-revenue, gross-margin, efficiency, refunds]\n\nrelated: [net-revenue, gross-margin, ad-spend, mer, refund-rate, ncac]\n\nprose:\n  why_it_matters: >-\n    Revenue can grow while the business earns less; contribution margin is the check. It takes\n    away what the goods cost and what the ads that sold them cost, leaving the money that pays\n    for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly\n    $345,000 after $560,000 of goods and $380,000 of ads, so a 10% rise in ad spend with flat\n    revenue cuts it by 11%.\n  pitfalls:\n    - Shipping labels, packaging, fulfilment and payment fees are variable costs too, often 10–15% of revenue. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.\n    - Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.\n    - When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check every channel reported spend before celebrating.\n    - Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"contribution-margin","name":"Contribution margin","aliases":["Contribution profit","Contribution after marketing","CM3"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"What is left of the week's net revenue after the cost of the goods sold and the ad spend that sold them.","formula":"Net revenue − cost of goods − ad spend, by week (subtract fulfilment and payment fees too when you record them)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"ad_spend","description":"Spend synced from each ad platform, one row per channel per day.","also_called":["ad insights","campaign cost data","cost import"],"properties":[{"name":"channel","description":"The platform or channel, such as meta, google or tiktok."},{"name":"spend","description":"Spend for the day, in the store's currency."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"queries":{"hogql":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(timestamp) AS week,\n  sumIf(toFloat(properties.total), event = 'order_completed') - sumIf(toFloat(properties.amount), event = 'order_refunded') AS net_revenue,\n  sumIf(toFloat(properties.cost_of_goods), event = 'order_completed') AS cost_of_goods,\n  sumIf(toFloat(properties.spend), event = 'ad_spend') AS ad_spend,\n  net_revenue - cost_of_goods - ad_spend AS value\nFROM events\nWHERE event IN ('order_completed', 'order_refunded', 'ad_spend')\n  AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n  AND timestamp < toStartOfWeek(now(), 1)\nGROUP BY week\nORDER BY week","postgres":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH weekly AS (\n  SELECT\n    date_trunc('week', occurred_at)::date AS week,\n    coalesce(sum((properties->>'total')::numeric) FILTER (WHERE event_name = 'order_completed'), 0)\n      - coalesce(sum((properties->>'amount')::numeric) FILTER (WHERE event_name = 'order_refunded'), 0) AS net_revenue,\n    coalesce(sum((properties->>'cost_of_goods')::numeric) FILTER (WHERE event_name = 'order_completed'), 0) AS cost_of_goods,\n    coalesce(sum((properties->>'spend')::numeric) FILTER (WHERE event_name = 'ad_spend'), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY 1\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;","bigquery":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH weekly AS (\n  SELECT\n    DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n    COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.total') AS FLOAT64), NULL)), 0)\n      - COALESCE(SUM(IF(event_name = 'order_refunded', SAFE_CAST(JSON_VALUE(properties, '$.amount') AS FLOAT64), NULL)), 0) AS net_revenue,\n    COALESCE(SUM(IF(event_name = 'order_completed', SAFE_CAST(JSON_VALUE(properties, '$.cost_of_goods') AS FLOAT64), NULL)), 0) AS cost_of_goods,\n    COALESCE(SUM(IF(event_name = 'ad_spend', SAFE_CAST(JSON_VALUE(properties, '$.spend') AS FLOAT64), NULL)), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY week\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;","snowflake":"-- Contribution margin: net revenue − cost of goods − ad spend. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nWITH weekly AS (\n  SELECT\n    DATE_TRUNC('week', occurred_at)::date AS week,\n    COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"total\"::float, NULL)), 0)\n      - COALESCE(SUM(IFF(event_name = 'order_refunded', properties:\"amount\"::float, NULL)), 0) AS net_revenue,\n    COALESCE(SUM(IFF(event_name = 'order_completed', properties:\"cost_of_goods\"::float, NULL)), 0) AS cost_of_goods,\n    COALESCE(SUM(IFF(event_name = 'ad_spend', properties:\"spend\"::float, NULL)), 0) AS ad_spend\n  FROM events\n  WHERE event_name IN ('order_completed', 'order_refunded', 'ad_spend')\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY 1\n)\nSELECT week, net_revenue, cost_of_goods, ad_spend, net_revenue - cost_of_goods - ad_spend AS value\nFROM weekly\nORDER BY week;"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":100000},"example":{"business":"store","level":291000,"volume":13300,"trend":0.15,"season":1},"drivers":[{"id":"tracking","label":"Spend and cost data","dropped":{"check":"Did ad spend sync twice for a platform, or did cost_of_goods change basis?","yes":"One channel's spend doubles with no change in its ads manager, or cost per unit jumps on one date."},"spiked":{"check":"Did an ad platform's spend sync fail, or did products start selling without a recorded cost?","yes":"One channel shows no spend for some days, or orders with no cost_of_goods appear. Fix the data before celebrating."}},{"id":"ad-spend","label":"Ad spend","metric":"ad-spend","feed":"ad-platforms","dropped":{"check":"Did ad spend rise faster than the revenue it brought, from a budget increase or a new campaign?","yes":"Spend rises while net revenue rises less, so each extra dollar of spend returns less than a dollar of margin."},"spiked":{"check":"Did spend fall, from a budget cut, a paused campaign or an ad account problem?","yes":"Spend falls while revenue holds this week; watch whether new customers fall in the weeks after."}},{"id":"net-revenue","label":"Net revenue","metric":"net-revenue","feed":"shopping","dropped":{"check":"Did net revenue fall, from fewer orders, smaller orders or more refunds?","yes":"Net revenue falls while spend and margin hold."},"spiked":{"check":"Is this a sale or holiday week, or did revenue rise for a reason that will last?","yes":"Net revenue rises while spend holds; the same week last year shows whether it's the calendar."}},{"id":"gross-margin","label":"Gross margin","metric":"gross-margin","dropped":{"check":"Did discounts, product mix or unit costs lower gross margin?","yes":"Gross margin falls while revenue and spend hold."},"spiked":{"check":"Did a sale end or a price rise lift gross margin?","yes":"Gross margin rises while revenue and spend hold."}},{"id":"efficiency","label":"Marketing efficiency","metric":"mer","dropped":{"check":"Did each ad dollar bring in less revenue, from rising CPMs or tired creative?","yes":"MER falls while spend holds."},"spiked":{"check":"Did each ad dollar bring in more revenue, or did a sale lift revenue on the same spend?","yes":"MER rises while spend holds; check the calendar before crediting the ads."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds jump, after a big sale, a bad batch or a delivery problem?","yes":"Refund rate rises while gross sales and spend hold."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refund rate returns to its usual level and margin recovers with it."}}],"diagnose_order":["tracking","ad-spend","net-revenue","gross-margin","efficiency","refunds"],"related":["net-revenue","gross-margin","ad-spend","mer","refund-rate","ncac"],"prose":{"why_it_matters":"Revenue can grow while the business earns less; contribution margin is the check. It takes away what the goods cost and what the ads that sold them cost, leaving the money that pays for salaries, rent and profit. At Northwind about $1.29M of net revenue leaves roughly $345,000 after $560,000 of goods and $380,000 of ads, so a 10% rise in ad spend with flat revenue cuts it by 11%.","pitfalls":["Shipping labels, packaging, fulfilment and payment fees are variable costs too, often 10–15% of revenue. Leaving them out overstates contribution margin; add them as a per-order estimate if you don't record them.","Ad spend is booked on the day it's spent, but the orders it drives can land days later, so a launch week reads low and the next week high. Use two-week sums when spend moves a lot.","When one platform's spend sync fails, contribution margin jumps by that platform's spend. Check every channel reported spend before celebrating.","Some teams stop before marketing and call that contribution margin. This spec takes ad spend out because that is the number that says whether growth pays."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "conversion-rate": { yaml: "id: conversion-rate\nname: Conversion rate\naliases:\n  - Ecommerce conversion rate\n  - Store conversion rate\n  - Online store conversion rate\n  - Session conversion rate\n  - Purchase conversion rate\nfamily: conversion\ncatalog_id: conversion_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that end in a paid order, the whole store funnel in one number.\n  formula: Sessions with a paid order ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $session_id\n        description: The session the order was placed in, passed from the browser to the server.\n\nnumerator:\n  label: Sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 0.02\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0206\n  volume: 600000\n  trend: 0.01\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?\n      yes: Orders in the store platform or payment processor hold while orders recorded in analytics fall.\n    spiked:\n      check: Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?\n      yes: Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    feed: cloudflare\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?\n      yes: Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting the rate without more orders?\n      yes: Sessions fall while orders hold. Check orders before celebrating.\n  - id: add-to-cart\n    label: Product pages and carts\n    metric: add-to-cart-rate\n    dropped:\n      check: Did fewer product viewers add to cart, from price, stock or a product page change?\n      yes: Add-to-cart rate falls by about as much as conversion while checkout steps hold.\n    spiked:\n      check: Did more product viewers add to cart, from a sale, a restock or a page change?\n      yes: Add-to-cart rate rises and checkout starts follow it.\n  - id: checkout\n    label: Checkout and payment\n    metric: checkout-conversion\n    feed: stripe\n    dropped:\n      check: Did more started checkouts fail, at shipping, payment or account creation?\n      yes: Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it.\n    spiked:\n      check: Did a checkout or payment problem from the week before clear?\n      yes: Checkout conversion returns to its usual level and conversion recovers with it.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only?\n      yes: Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, add-to-cart, checkout, device-split]\n\nrelated: [sessions, add-to-cart-rate, checkout-conversion, mobile-conversion-rate, revenue-per-session, product-view-rate]\n\nprose:\n  why_it_matters: >-\n    Conversion rate turns traffic into orders, so almost every change to the store shows up in\n    it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $60,000 a\n    week at a $100 order. It moves with who arrives as much as with the store, so read it\n    beside the traffic mix before crediting or blaming the site.\n  pitfalls:\n    - Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.\n    - Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.\n    - A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.\n    - Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.\n    - Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"conversion-rate","name":"Conversion rate","aliases":["Ecommerce conversion rate","Store conversion rate","Online store conversion rate","Session conversion rate","Purchase conversion rate"],"family":"conversion","catalog_id":"conversion_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that end in a paid order, the whole store funnel in one number.","formula":"Sessions with a paid order ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$session_id","description":"The session the order was placed in, passed from the browser to the server."}]}],"numerator":{"label":"Sessions with a paid order","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"sessions a week","typical":0.02,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0206,"volume":600000,"trend":0.01,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a consent banner, tag manager or checkout change stop orders, or their session ids, being recorded?","yes":"Orders in the store platform or payment processor hold while orders recorded in analytics fall."},"spiked":{"check":"Did page views stop being recorded somewhere, shrinking sessions while orders kept recording?","yes":"Sessions fall with no matching fall in ad clicks or server logs, often on one browser or after a consent change."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one when shoppers wait?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week? Compare with the same week last year before crediting the site.","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","feed":"cloudflare","dropped":{"check":"Did sessions grow from a low-intent source or from bots, such as broad paid social, a viral post or a crawler?","yes":"Sessions jump from one source whose conversion is a fraction of the rest, while orders barely move."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting the rate without more orders?","yes":"Sessions fall while orders hold. Check orders before celebrating."}},{"id":"add-to-cart","label":"Product pages and carts","metric":"add-to-cart-rate","dropped":{"check":"Did fewer product viewers add to cart, from price, stock or a product page change?","yes":"Add-to-cart rate falls by about as much as conversion while checkout steps hold."},"spiked":{"check":"Did more product viewers add to cart, from a sale, a restock or a page change?","yes":"Add-to-cart rate rises and checkout starts follow it."}},{"id":"checkout","label":"Checkout and payment","metric":"checkout-conversion","feed":"stripe","dropped":{"check":"Did more started checkouts fail, at shipping, payment or account creation?","yes":"Checkout conversion falls while add-to-cart holds; one step or one payment method explains most of it."},"spiked":{"check":"Did a checkout or payment problem from the week before clear?","yes":"Checkout conversion returns to its usual level and conversion recovers with it."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only?","yes":"Mobile falls while desktop is flat, which points at a release, a layout bug or a browser update."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","add-to-cart","checkout","device-split"],"related":["sessions","add-to-cart-rate","checkout-conversion","mobile-conversion-rate","revenue-per-session","product-view-rate"],"prose":{"why_it_matters":"Conversion rate turns traffic into orders, so almost every change to the store shows up in it eventually. At 600,000 sessions a week, a tenth of a point is 600 orders, about $60,000 a week at a $100 order. It moves with who arrives as much as with the store, so read it beside the traffic mix before crediting or blaming the site.","pitfalls":["Orders sent from the server often carry no session id and fall out of the numerator. Pass the browser's session id onto the order event or conversion reads low.","Orders ÷ sessions and sessions with an order ÷ sessions differ when shoppers place two orders in one visit. This spec counts sessions, like Shopify's online store conversion rate.","A new low-intent channel lowers conversion while adding orders. Never judge a move without orders and sessions beside it.","Channel splits need the session's landing source on every event, including the order; otherwise orders land in an unattributed bucket and every channel looks worse.","Comparing Black Friday week with the week before mixes intent. Compare with last year's Black Friday week instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "discount-rate": { yaml: "id: discount-rate\nname: Discount rate\naliases:\n  - Discount percentage\n  - Discounts as a share of sales\n  - Average discount rate\n  - Promotional discount rate\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.\n  formula: Discounts ÷ gross sales (order subtotals before discounts)\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded.\n      - name: coupon\n        description: The code redeemed on the order, if any.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Discounts\n  aggregate: sum\n  event: order_completed\n  property: discount\ndenominator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.1\n\nexample:\n  business: store\n  level: 0.089\n  volume: 13300\n  trend: 0.05\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a new discount app or checkout stop sending the discount on the order event?\n      yes: Orders with a coupon but a zero discount appear from one day.\n    spiked:\n      check: Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?\n      yes: The rate steps up on one release day with no new offer.\n  - id: calendar\n    label: Sales and the calendar\n    feed: shopping\n    dropped:\n      check: Did a sale end, or was last week a sale week?\n      yes: The same week last year shows the same fall once aligned on the event.\n    spiked:\n      check: Is a sale running, store-wide or on a code? Check orders rose with it.\n      yes: The rise matches the sale's dates, and the same week last year shows it too.\n  - id: codes\n    label: Discount codes\n    metric: promo-code-usage-rate\n    breakdown: coupon\n    dropped:\n      check: Did fewer orders use a code, because a code expired or a leaked one was disabled?\n      yes: Code usage falls by about as much as the discount rate.\n    spiked:\n      check: Did a code leak, or did an influencer or affiliate code take off?\n      yes: One code explains most of the rise, often on orders from channels it was never sent to.\n  - id: offer-depth\n    label: Depth of offers\n    dropped:\n      check: Did the offer get shallower, such as 15% off instead of 25%?\n      yes: The discount per discounted order falls while the number of discounted orders holds.\n    spiked:\n      check: Did a deeper offer run, or did two offers start stacking?\n      yes: The discount per discounted order rises; stacked orders carry both a code and an automatic offer.\n  - id: first-orders\n    label: Welcome offers\n    breakdown: is_first_order\n    dropped:\n      check: Did fewer first-time customers order with a welcome discount?\n      yes: The rate holds within each group and only the share of first orders moved.\n    spiked:\n      check: Did more first-time customers order with a welcome discount, or did the welcome offer grow?\n      yes: The rate on first orders rises, or first orders take a larger share.\n\ndiagnose_order: [tracking, calendar, codes, offer-depth, first-orders]\n\nrelated: [promo-code-usage-rate, gross-sales, gross-margin, aov, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Discount rate is the price of the growth a store buys with promotions, and it creeps as\n    welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody\n    chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra\n    point costs $14,500 of margin a week.\n  pitfalls:\n    - Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.\n    - Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.\n    - Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.\n    - Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"discount-rate","name":"Discount rate","aliases":["Discount percentage","Discounts as a share of sales","Average discount rate","Promotional discount rate"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of gross sales given away as discounts at checkout, from codes, automatic offers and bundle deals.","formula":"Discounts ÷ gross sales (order subtotals before discounts)"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount taken off the subtotal, from codes and automatic offers; shipping discounts excluded."},{"name":"coupon","description":"The code redeemed on the order, if any."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Discounts","aggregate":"sum","event":"order_completed","property":"discount"},"denominator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.1},"example":{"business":"store","level":0.089,"volume":13300,"trend":0.05,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a new discount app or checkout stop sending the discount on the order event?","yes":"Orders with a coupon but a zero discount appear from one day."},"spiked":{"check":"Did discount start including shipping discounts, gift cards or tax, or subtotal change basis?","yes":"The rate steps up on one release day with no new offer."}},{"id":"calendar","label":"Sales and the calendar","feed":"shopping","dropped":{"check":"Did a sale end, or was last week a sale week?","yes":"The same week last year shows the same fall once aligned on the event."},"spiked":{"check":"Is a sale running, store-wide or on a code? Check orders rose with it.","yes":"The rise matches the sale's dates, and the same week last year shows it too."}},{"id":"codes","label":"Discount codes","metric":"promo-code-usage-rate","breakdown":"coupon","dropped":{"check":"Did fewer orders use a code, because a code expired or a leaked one was disabled?","yes":"Code usage falls by about as much as the discount rate."},"spiked":{"check":"Did a code leak, or did an influencer or affiliate code take off?","yes":"One code explains most of the rise, often on orders from channels it was never sent to."}},{"id":"offer-depth","label":"Depth of offers","dropped":{"check":"Did the offer get shallower, such as 15% off instead of 25%?","yes":"The discount per discounted order falls while the number of discounted orders holds."},"spiked":{"check":"Did a deeper offer run, or did two offers start stacking?","yes":"The discount per discounted order rises; stacked orders carry both a code and an automatic offer."}},{"id":"first-orders","label":"Welcome offers","breakdown":"is_first_order","dropped":{"check":"Did fewer first-time customers order with a welcome discount?","yes":"The rate holds within each group and only the share of first orders moved."},"spiked":{"check":"Did more first-time customers order with a welcome discount, or did the welcome offer grow?","yes":"The rate on first orders rises, or first orders take a larger share."}}],"diagnose_order":["tracking","calendar","codes","offer-depth","first-orders"],"related":["promo-code-usage-rate","gross-sales","gross-margin","aov","net-revenue"],"prose":{"why_it_matters":"Discount rate is the price of the growth a store buys with promotions, and it creeps as welcome codes, influencer codes, leaked codes and stacked offers each add a point nobody chose. At Northwind, 8.5% of $1.45M of gross sales is about $123,000 a week, and each extra point costs $14,500 of margin a week.","pitfalls":["Markdowns made by lowering the product's price never show as discounts. A store that moves from codes to markdowns sees its discount rate fall while it gives away more.","Free-shipping offers aren't in subtotal or discount. Track their cost separately or the price of a free-shipping promotion stays invisible.","Discounts over gross sales measure cost, while the average discount on discounted orders measures offer depth. Don't compare one with the other's benchmark.","Read it with orders. A sale that adds five points of discount and 30% more orders may be the best week of the quarter; the same five points with flat orders gave margin away."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-margin": { yaml: "id: gross-margin\nname: Gross margin\naliases:\n  - Gross margin percentage\n  - Gross profit margin\n  - Product margin\nfamily: revenue\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of order revenue left after the cost of the goods sold, for orders paid this week.\n  formula: (Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: cost_of_goods\n        description: The landed cost of the order's items, purchase price plus inbound freight and duties.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Cost of goods\n  aggregate: sum\n  event: order_completed\n  property: cost_of_goods\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.55\n\nexample:\n  business: store\n  level: 0.532\n  volume: 13300\n  trend: -0.02\n\ndrivers:\n  - id: cost-data\n    label: Cost data\n    dropped:\n      check: Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?\n      yes: Cost per unit jumps for many products on one date, with no new purchase order behind it.\n    spiked:\n      check: Are products selling without a recorded cost, counting as free?\n      yes: The share of orders with no cost_of_goods rises, usually on new products.\n  - id: discounts\n    label: Discounts and sales\n    metric: discount-rate\n    feed: shopping\n    dropped:\n      check: Did discounts rise, from a sale, a code or a stacked offer?\n      yes: Discount rate rises by about as much as margin falls.\n    spiked:\n      check: Did a sale end, so orders carry less discount?\n      yes: Discount rate falls by about as much as margin rises.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n    spiked:\n      check: Did high-margin products take a larger share of sales?\n      yes: Each product's own margin holds and only the mix moved.\n  - id: landed-cost\n    label: Supplier, freight and duties\n    dropped:\n      check: Did supplier prices, freight or tariffs raise unit costs?\n      yes: Cost per unit rises on the same products, often when a new purchase order is received.\n    spiked:\n      check: Did a cheaper batch of stock start selling? Check it's not a cost data error first.\n      yes: Cost per unit falls on the products from one purchase order.\n  - id: pricing\n    label: Prices\n    dropped:\n      check: Did list prices fall, or did a price test lower them for some shoppers?\n      yes: Revenue per unit falls while cost per unit holds.\n    spiked:\n      check: Did a price rise take effect?\n      yes: Revenue per unit rises from the price change date while cost per unit holds.\n\ndiagnose_order: [cost-data, discounts, product-mix, landed-cost, pricing]\n\nrelated: [contribution-margin, discount-rate, net-revenue, aov, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Gross margin decides how much of each dollar of revenue is left for marketing, shipping and\n    everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to\n    spend with revenue unchanged; at Northwind that is about $40,000 a week.\n  pitfalls:\n    - Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.\n    - Products without a recorded cost count as free and pull margin up. New products are the usual culprit.\n    - This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.\n    - Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-margin","name":"Gross margin","aliases":["Gross margin percentage","Gross profit margin","Product margin"],"family":"revenue","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of order revenue left after the cost of the goods sold, for orders paid this week.","formula":"(Order revenue − cost of goods) ÷ order revenue, after discounts, before tax, shipping and refunds"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"cost_of_goods","description":"The landed cost of the order's items, purchase price plus inbound freight and duties."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Cost of goods","aggregate":"sum","event":"order_completed","property":"cost_of_goods"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.55},"example":{"business":"store","level":0.532,"volume":13300,"trend":-0.02},"drivers":[{"id":"cost-data","label":"Cost data","dropped":{"check":"Did cost_of_goods change basis, for example adding freight or loading a new supplier price list?","yes":"Cost per unit jumps for many products on one date, with no new purchase order behind it."},"spiked":{"check":"Are products selling without a recorded cost, counting as free?","yes":"The share of orders with no cost_of_goods rises, usually on new products."}},{"id":"discounts","label":"Discounts and sales","metric":"discount-rate","feed":"shopping","dropped":{"check":"Did discounts rise, from a sale, a code or a stacked offer?","yes":"Discount rate rises by about as much as margin falls."},"spiked":{"check":"Did a sale end, so orders carry less discount?","yes":"Discount rate falls by about as much as margin rises."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did low-margin products, such as bundles, clearance or a new hero product, take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."},"spiked":{"check":"Did high-margin products take a larger share of sales?","yes":"Each product's own margin holds and only the mix moved."}},{"id":"landed-cost","label":"Supplier, freight and duties","dropped":{"check":"Did supplier prices, freight or tariffs raise unit costs?","yes":"Cost per unit rises on the same products, often when a new purchase order is received."},"spiked":{"check":"Did a cheaper batch of stock start selling? Check it's not a cost data error first.","yes":"Cost per unit falls on the products from one purchase order."}},{"id":"pricing","label":"Prices","dropped":{"check":"Did list prices fall, or did a price test lower them for some shoppers?","yes":"Revenue per unit falls while cost per unit holds."},"spiked":{"check":"Did a price rise take effect?","yes":"Revenue per unit rises from the price change date while cost per unit holds."}}],"diagnose_order":["cost-data","discounts","product-mix","landed-cost","pricing"],"related":["contribution-margin","discount-rate","net-revenue","aov","refund-rate"],"prose":{"why_it_matters":"Gross margin decides how much of each dollar of revenue is left for marketing, shipping and everything else. A store at 58% margin that slips to 55% has lost about 5% of what it has to spend with revenue unchanged; at Northwind that is about $40,000 a week.","pitfalls":["Cost of goods should be the landed cost per unit, the purchase price plus inbound freight and duties. Supplier price alone overstates margin by several points for imported goods.","Products without a recorded cost count as free and pull margin up. New products are the usual culprit.","This spec matches each order's revenue to its own cost and leaves refunds out, because a refund event carries no cost. Read refund rate beside it.","Shipping, packaging and payment fees aren't cost of goods. Including them mixes gross margin with contribution margin and breaks comparisons with industry figures."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "gross-sales": { yaml: "id: gross-sales\nname: Gross sales\naliases:\n  - Gross revenue\n  - Gross merchandise value\n  - GMV\n  - Sales before discounts\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.\n  formula: Sum of order subtotals before discounts, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: subtotal\n        description: Price × quantity of every item, before discounts, tax and shipping.\n      - name: discount\n        description: The total discount on the order, read in discount rate.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Gross sales\n  aggregate: sum\n  event: order_completed\n  property: subtotal\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 300000\n\nexample:\n  business: store\n  level: 1450000\n  volume: 13300\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did subtotal stop being sent, or change meaning, for example to after discounts?\n      yes: Subtotal ÷ order total jumps or falls on one release day with no change in offers.\n    spiked:\n      check: Did subtotal start including tax or shipping, or did one currency start arriving unconverted?\n      yes: Order subtotals jump for one country or channel from one day.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or gifting week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or gifting week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth before discounts?\n      yes: Orders fall by about as much as gross sales.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as gross sales.\n  - id: discounts\n    label: Promotions\n    metric: discount-rate\n    dropped:\n      check: Did a promotion end that had been pulling demand forward?\n      yes: Discount rate falls with gross sales while net revenue falls less.\n    spiked:\n      check: Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.\n      yes: Discount rate rises with gross sales, and net revenue grows far less.\n  - id: basket-size\n    label: Items per order\n    metric: units-per-order\n    dropped:\n      check: Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?\n      yes: Units per order fall while orders hold.\n    spiked:\n      check: Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?\n      yes: Units per order rise from the day the offer started.\n  - id: price-and-mix\n    label: Prices and product mix\n    dropped:\n      check: Did prices fall, or did sales shift toward cheaper products?\n      yes: Units hold while the average price per unit falls, often on a few products.\n    spiked:\n      check: Did prices rise, a premium product launch, or a few very large orders land?\n      yes: The average price per unit rises, or the largest orders explain most of the jump.\n\ndiagnose_order: [tracking, calendar, orders, discounts, basket-size, price-and-mix]\n\nrelated: [net-revenue, discount-rate, refund-rate, aov, units-per-order]\n\nprose:\n  why_it_matters: >-\n    Gross sales measure demand at full price, before the store decides what to give back.\n    Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M\n    of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion\n    that grows gross sales 20% while net revenue grows 5% bought most of its growth.\n  pitfalls:\n    - Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.\n    - Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.\n    - Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.\n    - A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"gross-sales","name":"Gross sales","aliases":["Gross revenue","Gross merchandise value","GMV","Sales before discounts"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The value of products sold this week at their selling price, before discounts, refunds, tax and shipping.","formula":"Sum of order subtotals before discounts, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"subtotal","description":"Price × quantity of every item, before discounts, tax and shipping."},{"name":"discount","description":"The total discount on the order, read in discount rate."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Gross sales","aggregate":"sum","event":"order_completed","property":"subtotal"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":300000},"example":{"business":"store","level":1450000,"volume":13300,"trend":0.2,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did subtotal stop being sent, or change meaning, for example to after discounts?","yes":"Subtotal ÷ order total jumps or falls on one release day with no change in offers."},"spiked":{"check":"Did subtotal start including tax or shipping, or did one currency start arriving unconverted?","yes":"Order subtotals jump for one country or channel from one day."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or gifting week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or gifting week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth before discounts?","yes":"Orders fall by about as much as gross sales."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as gross sales."}},{"id":"discounts","label":"Promotions","metric":"discount-rate","dropped":{"check":"Did a promotion end that had been pulling demand forward?","yes":"Discount rate falls with gross sales while net revenue falls less."},"spiked":{"check":"Is a promotion lifting gross sales while discounts eat the gain? Check net revenue before celebrating.","yes":"Discount rate rises with gross sales, and net revenue grows far less."}},{"id":"basket-size","label":"Items per order","metric":"units-per-order","dropped":{"check":"Did shoppers buy fewer items per order, after a bundle ended or a free-shipping threshold fell?","yes":"Units per order fall while orders hold."},"spiked":{"check":"Did a bundle, multi-buy offer or higher free-shipping threshold add items to orders?","yes":"Units per order rise from the day the offer started."}},{"id":"price-and-mix","label":"Prices and product mix","dropped":{"check":"Did prices fall, or did sales shift toward cheaper products?","yes":"Units hold while the average price per unit falls, often on a few products."},"spiked":{"check":"Did prices rise, a premium product launch, or a few very large orders land?","yes":"The average price per unit rises, or the largest orders explain most of the jump."}}],"diagnose_order":["tracking","calendar","orders","discounts","basket-size","price-and-mix"],"related":["net-revenue","discount-rate","refund-rate","aov","units-per-order"],"prose":{"why_it_matters":"Gross sales measure demand at full price, before the store decides what to give back. Read beside net revenue, the gap is the cost of promotions and returns; at Northwind, $1.45M of gross sales becomes $1.33M after discounts and about $1.29M after refunds. A promotion that grows gross sales 20% while net revenue grows 5% bought most of its growth.","pitfalls":["Shopify's gross sales is price × quantity before discounts, but some platforms' gross revenue includes tax and shipping. Say which one you report; this spec excludes both.","Marking a price down on the product lowers gross sales itself, while a code adds a discount. Two sales of the same depth look different here, so know which kind each one was.","Gross sales rise with every promotion that works on volume. Never report them without net revenue beside them.","A few wholesale or bulk orders can move a small store's week by 10% or more. Check the order count and the largest orders before the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mobile-conversion-rate": { yaml: "id: mobile-conversion-rate\nname: Mobile conversion rate\naliases:\n  - Mobile ecommerce conversion rate\n  - Mobile store conversion rate\n  - Mobile CVR\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.\n  formula: Mobile sessions with a paid order ÷ mobile sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n      - name: $device_type\n        description: Mobile, Desktop or Tablet, from the browser's user agent.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id and device type.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: $device_type\n        description: The device the order was placed on, copied from the browser session.\n\nnumerator:\n  label: Mobile sessions with a paid order\n  aggregate: unique_sessions\n  event: order_completed\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\ndenominator:\n  label: Mobile sessions\n  aggregate: unique_sessions\n  event: $pageview\n  where:\n    - property: $device_type\n      op: eq\n      value: Mobile\n\nnoise:\n  type: binomial\n  min_denominator: 2000\n  volume_unit: mobile sessions a week\n  typical: 0.016\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.0204\n  volume: 408000\n  trend: 0.04\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Are orders losing their device type or session id, for example after moving the order event to the server?\n      yes: Orders with no device type rise while mobile orders fall by about as much.\n    spiked:\n      check: Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?\n      yes: Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero.\n  - id: os-and-browsers\n    label: iOS, Android and browser releases\n    breakdown: $os\n    feed: app-stores\n    dropped:\n      check: Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?\n      yes: The drop concentrates on one operating system or browser version, from its release date.\n    spiked:\n      check: Did a platform update or your own fix clear a problem from an earlier release?\n      yes: The affected system returns to its usual rate and the others never moved.\n  - id: mobile-release\n    label: Mobile site release\n    dropped:\n      check: Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?\n      yes: The drop starts on the release day and desktop conversion holds.\n    spiked:\n      check: Did a mobile release or test ship, and is it on for everyone?\n      yes: The rise starts on the release day; confirm it isn't a tracking change before crediting it.\n  - id: traffic-mix\n    label: Social and in-app traffic\n    breakdown: utm_source\n    dropped:\n      check: Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?\n      yes: Sessions from one social source grow, and those sessions convert at a fraction of the mobile web.\n    spiked:\n      check: Did a social campaign pause, or did email and branded search take a larger share of mobile visits?\n      yes: Each source's own rate holds and only the mix moved.\n  - id: wallets\n    label: Wallets and payment sheets\n    feed: stripe\n    dropped:\n      check: Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?\n      yes: Wallet payments on mobile fall while card payments hold.\n    spiked:\n      check: Did a wallet button launch on product pages or in the cart?\n      yes: Wallet orders rise from the launch day and mobile checkouts get shorter.\n\ndiagnose_order: [tracking, os-and-browsers, mobile-release, traffic-mix, wallets]\n\nrelated: [conversion-rate, mobile-session-share, checkout-conversion, payment-success-rate, bounce-rate]\n\nprose:\n  why_it_matters: >-\n    Phones bring about two thirds of store sessions but convert well below desktop; at\n    Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things,\n    such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth\n    of the gap on 408,000 mobile sessions a week is about 800 orders.\n  pitfalls:\n    - Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.\n    - Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.\n    - In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.\n    - A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mobile-conversion-rate","name":"Mobile conversion rate","aliases":["Mobile ecommerce conversion rate","Mobile store conversion rate","Mobile CVR"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions on phones that end in a paid order. Tablets are left out, as GA4 reports them separately.","formula":"Mobile sessions with a paid order ÷ mobile sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."},{"name":"$device_type","description":"Mobile, Desktop or Tablet, from the browser's user agent."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id and device type.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"$device_type","description":"The device the order was placed on, copied from the browser session."}]}],"numerator":{"label":"Mobile sessions with a paid order","aggregate":"unique_sessions","event":"order_completed","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"denominator":{"label":"Mobile sessions","aggregate":"unique_sessions","event":"$pageview","where":[{"property":"$device_type","op":"eq","value":"Mobile"}]},"noise":{"type":"binomial","min_denominator":2000,"volume_unit":"mobile sessions a week","typical":0.016,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.0204,"volume":408000,"trend":0.04,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Are orders losing their device type or session id, for example after moving the order event to the server?","yes":"Orders with no device type rise while mobile orders fall by about as much."},"spiked":{"check":"Did mobile page views stop recording somewhere, or did tablets start reporting as mobile?","yes":"Mobile sessions fall with no matching fall in mobile ad clicks, or tablet sessions drop to near zero."}},{"id":"os-and-browsers","label":"iOS, Android and browser releases","breakdown":"$os","feed":"app-stores","dropped":{"check":"Did an iOS, Android, Safari or Chrome release this week break a payment sheet, autofill or a script?","yes":"The drop concentrates on one operating system or browser version, from its release date."},"spiked":{"check":"Did a platform update or your own fix clear a problem from an earlier release?","yes":"The affected system returns to its usual rate and the others never moved."}},{"id":"mobile-release","label":"Mobile site release","dropped":{"check":"Did a release change the mobile product page, menu, sticky add-to-cart bar or checkout layout?","yes":"The drop starts on the release day and desktop conversion holds."},"spiked":{"check":"Did a mobile release or test ship, and is it on for everyone?","yes":"The rise starts on the release day; confirm it isn't a tracking change before crediting it."}},{"id":"traffic-mix","label":"Social and in-app traffic","breakdown":"utm_source","dropped":{"check":"Did more mobile traffic come from social ads that open in Instagram or TikTok's in-app browser?","yes":"Sessions from one social source grow, and those sessions convert at a fraction of the mobile web."},"spiked":{"check":"Did a social campaign pause, or did email and branded search take a larger share of mobile visits?","yes":"Each source's own rate holds and only the mix moved."}},{"id":"wallets","label":"Wallets and payment sheets","feed":"stripe","dropped":{"check":"Did Apple Pay, Google Pay or Shop Pay drop out of mobile checkout or start failing?","yes":"Wallet payments on mobile fall while card payments hold."},"spiked":{"check":"Did a wallet button launch on product pages or in the cart?","yes":"Wallet orders rise from the launch day and mobile checkouts get shorter."}}],"diagnose_order":["tracking","os-and-browsers","mobile-release","traffic-mix","wallets"],"related":["conversion-rate","mobile-session-share","checkout-conversion","payment-success-rate","bounce-rate"],"prose":{"why_it_matters":"Phones bring about two thirds of store sessions but convert well below desktop; at Northwind, 1.9% against 2.9%. Mobile is where a store loses the most orders to small things, such as a hidden button, a slow page or a payment sheet that doesn't open. Closing a fifth of the gap on 408,000 mobile sessions a week is about 800 orders.","pitfalls":["Orders sent from the server carry no device type, so mobile conversion reads near zero. Copy the device type and session id from the browser onto the order event.","Tablets convert closer to desktop than to phones. This spec leaves them out; including them reads higher and isn't comparable.","In-app browsers from Instagram and TikTok count as mobile sessions but convert far below the mobile web, so a social campaign lowers the rate without anything breaking.","A shopper who browses on a phone and buys on a laptop counts as a lost mobile session and a desktop order. Read mobile conversion for change over time, not as what mobile is worth."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "mrr": { yaml: "id: mrr\nname: Monthly recurring revenue\naliases:\n  - MRR\n  - Monthly recurring revenue (MRR)\nfamily: subscription\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.\n  formula: Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC\n\nevents:\n  - name: subscription_updated\n    description: Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.\n    also_called: [customer.subscription.updated, Subscription Updated, subscription_changed]\n    properties:\n      - name: subscription_id\n        description: The billing system's subscription id.\n      - name: mrr\n        description: The subscription's monthly amount after the change, after discounts, before tax.\n      - name: status\n        description: active, trialing, past_due or canceled.\n\nnumerator:\n  label: MRR at week end\n  aggregate: sum\n  event: subscription_updated\n  property: mrr\n\nqueries:\n  hogql: |-\n    -- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\n    SELECT toString(week) AS week, sum(mrr) AS value\n    FROM (\n      SELECT\n        w.week AS week,\n        e.subscription_id AS subscription_id,\n        argMax(e.mrr, e.ts) AS mrr,\n        argMax(e.status, e.ts) AS status\n      FROM (\n        SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n      ) AS w\n      CROSS JOIN (\n        SELECT\n          toString(properties.subscription_id) AS subscription_id,\n          toFloat(properties.mrr) AS mrr,\n          toString(properties.status) AS status,\n          timestamp AS ts\n        FROM events\n        WHERE event = 'subscription_updated'\n      ) AS e\n      WHERE e.ts < w.week + toIntervalWeek(1)\n      GROUP BY week, subscription_id\n    )\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT generate_series(\n        date_trunc('week', now() - interval '26 weeks'),\n        date_trunc('week', now()) - interval '1 week',\n        interval '1 week'\n      ) AS week\n    ),\n    latest AS (\n      SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n        w.week,\n        (e.properties->>'mrr')::numeric AS mrr,\n        e.properties->>'status' AS status\n      FROM weeks w\n      JOIN events e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < w.week + interval '1 week'\n      ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n    )\n    SELECT week::date AS week, sum(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  bigquery: |-\n    -- MRR at the end of each week from a subscription change log.\n    WITH weeks AS (\n      SELECT week\n      FROM UNNEST(GENERATE_DATE_ARRAY(\n        DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n        DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n        INTERVAL 1 WEEK\n      )) AS week\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n        CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n        JSON_VALUE(e.properties, '$.status') AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\n    WITH weeks AS (\n      SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n      FROM TABLE(GENERATOR(ROWCOUNT => 26))\n    ),\n    latest AS (\n      SELECT\n        w.week,\n        e.properties:subscription_id::string AS subscription_id,\n        e.properties:mrr::float AS mrr,\n        e.properties:status::string AS status\n      FROM weeks AS w\n      JOIN events AS e\n        ON e.event_name = 'subscription_updated'\n       AND e.occurred_at < DATEADD(week, 1, w.week)\n      QUALIFY ROW_NUMBER() OVER (\n        PARTITION BY w.week, e.properties:subscription_id::string\n        ORDER BY e.occurred_at DESC\n      ) = 1\n    )\n    SELECT week, SUM(mrr) AS value\n    FROM latest\n    WHERE status IN ('active', 'past_due')\n    GROUP BY week\n    ORDER BY week;\n\nnoise:\n  type: process\n  min_denominator: 20\n  volume_unit: active subscriptions\n  typical: 180000\n\nexample:\n  business: saas\n  level: 240000\n  volume: 1900\n  trend: 0.35\n\ndrivers:\n  - id: new-mrr\n    label: New MRR\n    metric: new-mrr\n    dropped:\n      check: Did fewer new customers start paying, or start on smaller plans?\n      yes: New MRR falls below its usual range while churn holds.\n    spiked:\n      check: Did a launch, a sales push or one large deal add new MRR?\n      yes: New MRR jumps; check whether one customer accounts for most of it.\n  - id: expansion\n    label: Expansion\n    metric: expansion-mrr\n    dropped:\n      check: Did upgrades and seat additions slow?\n      yes: Expansion MRR falls while new and churned MRR hold.\n    spiked:\n      check: Did a price change or a usage limit push customers to upgrade?\n      yes: Expansion MRR jumps in the week the change shipped.\n  - id: churn\n    label: Churned and contracted MRR\n    metric: churned-mrr\n    feed: stripe\n    dropped:\n      check: Did cancellations, downgrades or failed renewals rise?\n      yes: Churned MRR rises; failed payments or one large account explain most of it.\n    spiked:\n      check: Did churn fall unusually low, or did failed payments recover?\n      yes: Churned MRR falls and recovered dunning payments appear.\n  - id: billing-calendar\n    label: Billing calendar\n    dropped:\n      check: Did a cohort of annual plans come up for renewal this week?\n      yes: A cluster of renewals dated one year after a big signup month.\n    spiked:\n      check: Is a migration or a currency revaluation changing amounts without customers acting?\n      yes: Many subscriptions change amount on the same day with no plan change.\n\ndiagnose_order: [billing-calendar, churn, new-mrr, expansion]\n\nrelated: [new-mrr, expansion-mrr, churned-mrr, net-new-mrr, arpa]\n\nprose:\n  why_it_matters: >-\n    MRR is the stock that every other subscription number flows into: new and expansion MRR\n    add to it, churn and contraction take from it. Because it is a stock, it barely moves week\n    to week, which is exactly why a small move matters. Read its flows to see why it moved;\n    read MRR itself to see whether the business is growing.\n  pitfalls:\n    - Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.\n    - Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.\n    - Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.\n    - A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"mrr","name":"Monthly recurring revenue","aliases":["MRR","Monthly recurring revenue (MRR)"],"family":"subscription","kind":"currency","polarity":"up-is-good","definition":{"one_line":"The monthly value of every active subscription at the end of the week, with annual plans divided by twelve.","formula":"Sum of active subscriptions' monthly amounts, measured Sunday 23:59 UTC"},"events":[{"name":"subscription_updated","description":"Any change to a subscription's plan, quantity, discount or status, with its new monthly amount.","also_called":["customer.subscription.updated","Subscription Updated","subscription_changed"],"properties":[{"name":"subscription_id","description":"The billing system's subscription id."},{"name":"mrr","description":"The subscription's monthly amount after the change, after discounts, before tax."},{"name":"status","description":"active, trialing, past_due or canceled."}]}],"numerator":{"label":"MRR at week end","aggregate":"sum","event":"subscription_updated","property":"mrr"},"queries":{"hogql":"-- MRR at the end of each of the last 26 weeks: each subscription's latest state before the week closed.\nSELECT toString(week) AS week, sum(mrr) AS value\nFROM (\n  SELECT\n    w.week AS week,\n    e.subscription_id AS subscription_id,\n    argMax(e.mrr, e.ts) AS mrr,\n    argMax(e.status, e.ts) AS status\n  FROM (\n    SELECT arrayJoin(arrayMap(i -> toMonday(now()) - toIntervalWeek(i), range(1, 27))) AS week\n  ) AS w\n  CROSS JOIN (\n    SELECT\n      toString(properties.subscription_id) AS subscription_id,\n      toFloat(properties.mrr) AS mrr,\n      toString(properties.status) AS status,\n      timestamp AS ts\n    FROM events\n    WHERE event = 'subscription_updated'\n  ) AS e\n  WHERE e.ts < w.week + toIntervalWeek(1)\n  GROUP BY week, subscription_id\n)\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week","postgres":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT generate_series(\n    date_trunc('week', now() - interval '26 weeks'),\n    date_trunc('week', now()) - interval '1 week',\n    interval '1 week'\n  ) AS week\n),\nlatest AS (\n  SELECT DISTINCT ON (w.week, e.properties->>'subscription_id')\n    w.week,\n    (e.properties->>'mrr')::numeric AS mrr,\n    e.properties->>'status' AS status\n  FROM weeks w\n  JOIN events e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < w.week + interval '1 week'\n  ORDER BY w.week, e.properties->>'subscription_id', e.occurred_at DESC\n)\nSELECT week::date AS week, sum(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","bigquery":"-- MRR at the end of each week from a subscription change log.\nWITH weeks AS (\n  SELECT week\n  FROM UNNEST(GENERATE_DATE_ARRAY(\n    DATE_TRUNC(DATE_SUB(CURRENT_DATE(), INTERVAL 26 WEEK), ISOWEEK),\n    DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 1 WEEK),\n    INTERVAL 1 WEEK\n  )) AS week\n),\nlatest AS (\n  SELECT\n    w.week,\n    JSON_VALUE(e.properties, '$.subscription_id') AS subscription_id,\n    CAST(JSON_VALUE(e.properties, '$.mrr') AS FLOAT64) AS mrr,\n    JSON_VALUE(e.properties, '$.status') AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND DATE(e.occurred_at) < DATE_ADD(w.week, INTERVAL 1 WEEK)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, JSON_VALUE(e.properties, '$.subscription_id')\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;","snowflake":"-- MRR at the end of each week from a subscription change log. Assumes WEEK_START = 1 (Monday).\nWITH weeks AS (\n  SELECT DATEADD(week, -SEQ4(), DATE_TRUNC('week', DATEADD(week, -1, CURRENT_DATE()))) AS week\n  FROM TABLE(GENERATOR(ROWCOUNT => 26))\n),\nlatest AS (\n  SELECT\n    w.week,\n    e.properties:subscription_id::string AS subscription_id,\n    e.properties:mrr::float AS mrr,\n    e.properties:status::string AS status\n  FROM weeks AS w\n  JOIN events AS e\n    ON e.event_name = 'subscription_updated'\n   AND e.occurred_at < DATEADD(week, 1, w.week)\n  QUALIFY ROW_NUMBER() OVER (\n    PARTITION BY w.week, e.properties:subscription_id::string\n    ORDER BY e.occurred_at DESC\n  ) = 1\n)\nSELECT week, SUM(mrr) AS value\nFROM latest\nWHERE status IN ('active', 'past_due')\nGROUP BY week\nORDER BY week;"},"noise":{"type":"process","min_denominator":20,"volume_unit":"active subscriptions","typical":180000},"example":{"business":"saas","level":240000,"volume":1900,"trend":0.35},"drivers":[{"id":"new-mrr","label":"New MRR","metric":"new-mrr","dropped":{"check":"Did fewer new customers start paying, or start on smaller plans?","yes":"New MRR falls below its usual range while churn holds."},"spiked":{"check":"Did a launch, a sales push or one large deal add new MRR?","yes":"New MRR jumps; check whether one customer accounts for most of it."}},{"id":"expansion","label":"Expansion","metric":"expansion-mrr","dropped":{"check":"Did upgrades and seat additions slow?","yes":"Expansion MRR falls while new and churned MRR hold."},"spiked":{"check":"Did a price change or a usage limit push customers to upgrade?","yes":"Expansion MRR jumps in the week the change shipped."}},{"id":"churn","label":"Churned and contracted MRR","metric":"churned-mrr","feed":"stripe","dropped":{"check":"Did cancellations, downgrades or failed renewals rise?","yes":"Churned MRR rises; failed payments or one large account explain most of it."},"spiked":{"check":"Did churn fall unusually low, or did failed payments recover?","yes":"Churned MRR falls and recovered dunning payments appear."}},{"id":"billing-calendar","label":"Billing calendar","dropped":{"check":"Did a cohort of annual plans come up for renewal this week?","yes":"A cluster of renewals dated one year after a big signup month."},"spiked":{"check":"Is a migration or a currency revaluation changing amounts without customers acting?","yes":"Many subscriptions change amount on the same day with no plan change."}}],"diagnose_order":["billing-calendar","churn","new-mrr","expansion"],"related":["new-mrr","expansion-mrr","churned-mrr","net-new-mrr","arpa"],"prose":{"why_it_matters":"MRR is the stock that every other subscription number flows into: new and expansion MRR add to it, churn and contraction take from it. Because it is a stock, it barely moves week to week, which is exactly why a small move matters. Read its flows to see why it moved; read MRR itself to see whether the business is growing.","pitfalls":["Counting trials or unpaid invoices as MRR inflates it until they lapse. Count only subscriptions that pay.","Annual plans divided by twelve smooth revenue; booking them in full the month they are paid makes MRR spike and fall back.","Discounts and coupons belong in MRR at the discounted amount, or MRR overstates what customers pay.","A week with a currency revaluation or a price migration moves MRR with no change in customers. Note it on the week."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "net-revenue": { yaml: "id: net-revenue\nname: Net revenue\naliases:\n  - Weekly revenue\n  - Net sales\nfamily: revenue\ncatalog_id: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.\n  formula: Sum of order totals − refunds issued, excluding tax and shipping\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded]\n    properties:\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n\nnumerator:\n  label: Net revenue\n  aggregate: sum\n  event: order_completed\n  property: total\nsubtract:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\n\nnoise:\n  type: compound\n  cv: 0.9\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 400000\n\nexample:\n  business: store\n  level: 1300000\n  volume: 13000\n  trend: 0.2\n  season: 1\n\ndrivers:\n  - id: orders\n    label: Orders\n    metric: orders\n    dropped:\n      check: Did the number of orders fall, or only what each order is worth?\n      yes: Orders fall by about as much as revenue while order value holds.\n    spiked:\n      check: Is the rise in the number of orders rather than their size?\n      yes: Orders rise by about as much as revenue while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did the average order shrink, from a discount, a mix shift or fewer items per order?\n      yes: Order value falls while the number of orders holds.\n    spiked:\n      check: Did a few large orders or a price rise lift the average?\n      yes: Order value jumps, often driven by a handful of orders far above the usual size.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors?\n      yes: Sessions rise in one channel, and conversion holds.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which step?\n      yes: Conversion falls while traffic holds; one funnel step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which step?\n      yes: Conversion rises while traffic holds; one funnel step explains most of it.\n  - id: refunds\n    label: Refunds\n    metric: refund-rate\n    dropped:\n      check: Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?\n      yes: Gross sales hold while refunds rise.\n    spiked:\n      check: Did refunds fall back after an unusual week?\n      yes: Refunds return to their usual share and net revenue recovers.\n  - id: calendar\n    label: Calendar\n    feed: shopping\n    dropped:\n      check: Is last week's comparison a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this week a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n\ndiagnose_order: [calendar, orders, order-value, traffic, conversion, refunds]\n\nrelated: [orders, aov, conversion-rate, gross-sales, refund-rate]\n\nprose:\n  why_it_matters: >-\n    Revenue is the number everyone reads first, which is why it is the worst number to act on\n    alone. It is orders times order value, and orders are traffic times conversion; a move in\n    revenue is only useful once you know which of those moved. Most weeks, nothing did, and the\n    honest answer is that the change is the ordinary wobble of a few thousand orders.\n  pitfalls:\n    - Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.\n    - Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.\n    - A few very large orders can move a small store's week by 10% or more. Check the order count before the total.\n    - Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"net-revenue","name":"Net revenue","aliases":["Weekly revenue","Net sales"],"family":"revenue","catalog_id":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue after discounts and refunds, before tax and shipping, for orders paid this week.","formula":"Sum of order totals − refunds issued, excluding tax and shipping"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]},{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded"],"properties":[{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]}],"numerator":{"label":"Net revenue","aggregate":"sum","event":"order_completed","property":"total"},"subtract":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"noise":{"type":"compound","cv":0.9,"min_denominator":50,"volume_unit":"orders a week","typical":400000},"example":{"business":"store","level":1300000,"volume":13000,"trend":0.2,"season":1},"drivers":[{"id":"orders","label":"Orders","metric":"orders","dropped":{"check":"Did the number of orders fall, or only what each order is worth?","yes":"Orders fall by about as much as revenue while order value holds."},"spiked":{"check":"Is the rise in the number of orders rather than their size?","yes":"Orders rise by about as much as revenue while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did the average order shrink, from a discount, a mix shift or fewer items per order?","yes":"Order value falls while the number of orders holds."},"spiked":{"check":"Did a few large orders or a price rise lift the average?","yes":"Order value jumps, often driven by a handful of orders far above the usual size."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors?","yes":"Sessions rise in one channel, and conversion holds."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which step?","yes":"Conversion falls while traffic holds; one funnel step explains most of it."},"spiked":{"check":"Did more visits buy, and at which step?","yes":"Conversion rises while traffic holds; one funnel step explains most of it."}},{"id":"refunds","label":"Refunds","metric":"refund-rate","dropped":{"check":"Did refunds spike, from a bad batch, a delivery failure or a chargeback wave?","yes":"Gross sales hold while refunds rise."},"spiked":{"check":"Did refunds fall back after an unusual week?","yes":"Refunds return to their usual share and net revenue recovers."}},{"id":"calendar","label":"Calendar","feed":"shopping","dropped":{"check":"Is last week's comparison a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this week a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}}],"diagnose_order":["calendar","orders","order-value","traffic","conversion","refunds"],"related":["orders","aov","conversion-rate","gross-sales","refund-rate"],"prose":{"why_it_matters":"Revenue is the number everyone reads first, which is why it is the worst number to act on alone. It is orders times order value, and orders are traffic times conversion; a move in revenue is only useful once you know which of those moved. Most weeks, nothing did, and the honest answer is that the change is the ordinary wobble of a few thousand orders.","pitfalls":["Booking revenue when the order is placed but refunds when they are issued mixes two weeks. Report both by the week they happen and say so.","Including tax and shipping makes revenue move with tax rules and carrier prices you don't control.","A few very large orders can move a small store's week by 10% or more. Check the order count before the total.","Revenue in several currencies needs one fixed exchange rate per week, or currency moves look like sales."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "orders": { yaml: "id: orders\nname: Orders\naliases:\n  - Order count\n  - Weekly orders\n  - Number of orders\n  - Paid orders\n  - Transactions\nfamily: revenue\ncatalog_id: orders\nkind: count\npolarity: up-is-good\n\ndefinition:\n  one_line: The number of paid orders placed in the week, each counted once, before any refunds.\n  formula: Count of paid orders, by the week they were paid\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server or the payment processor, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: poisson\n  min_denominator: 30\n  volume_unit: orders a week\n  typical: 3000\n\nexample:\n  business: store\n  level: 13300\n  volume: 13300\n  trend: 0.2\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did recorded orders fall while the store platform or payment processor shows the usual count?\n      yes: The processor's order count holds, often after a checkout, consent or tag change.\n    spiked:\n      check: Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?\n      yes: Recorded orders exceed the processor's count, or the same order_id appears more than once.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week, or is this the week before one?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: payments\n    label: Payment outages\n    metric: payment-success-rate\n    feed: stripe\n    dropped:\n      check: Did a processor incident or a fraud rule block payments for part of the week?\n      yes: Payment success falls for one gateway or method during the hours orders are missing.\n    spiked:\n      check: Did a payment problem from the week before clear?\n      yes: Payment success returns to its usual level and orders recover with it.\n  - id: traffic\n    label: Traffic\n    metric: sessions\n    feed: google-search\n    dropped:\n      check: Did fewer people arrive, and from which channel?\n      yes: Sessions fall in one channel by about as much as orders do, while conversion holds.\n    spiked:\n      check: Did a campaign, press mention or ranking change bring more visitors who buy?\n      yes: Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did the share of visits that buy fall, and at which funnel step?\n      yes: Conversion falls while traffic holds; one step explains most of it.\n    spiked:\n      check: Did more visits buy, and at which funnel step?\n      yes: Conversion rises while traffic holds; one step explains most of it.\n  - id: first-orders\n    label: First vs repeat orders\n    metric: new-customers\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?\n      yes: New customers fall by about as much as orders.\n    spiked:\n      check: Did an email, a launch or a restock bring back past customers?\n      yes: Repeat orders jump while first orders hold.\n\ndiagnose_order: [tracking, calendar, payments, traffic, conversion, first-orders]\n\nrelated: [net-revenue, aov, conversion-rate, sessions, new-customers]\n\nprose:\n  why_it_matters: >-\n    Orders are the store's heartbeat, a count of decisions to buy, free of price and basket\n    effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with\n    800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.\n  pitfalls:\n    - Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.\n    - Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.\n    - Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.\n    - Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"orders","name":"Orders","aliases":["Order count","Weekly orders","Number of orders","Paid orders","Transactions"],"family":"revenue","catalog_id":"orders","kind":"count","polarity":"up-is-good","definition":{"one_line":"The number of paid orders placed in the week, each counted once, before any refunds.","formula":"Count of paid orders, by the week they were paid"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server or the payment processor, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"poisson","min_denominator":30,"volume_unit":"orders a week","typical":3000},"example":{"business":"store","level":13300,"volume":13300,"trend":0.2},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did recorded orders fall while the store platform or payment processor shows the usual count?","yes":"The processor's order count holds, often after a checkout, consent or tag change."},"spiked":{"check":"Are orders duplicated by thank-you page reloads or webhook retries, or are test orders included?","yes":"Recorded orders exceed the processor's count, or the same order_id appears more than once."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week, or is this the week before one?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"payments","label":"Payment outages","metric":"payment-success-rate","feed":"stripe","dropped":{"check":"Did a processor incident or a fraud rule block payments for part of the week?","yes":"Payment success falls for one gateway or method during the hours orders are missing."},"spiked":{"check":"Did a payment problem from the week before clear?","yes":"Payment success returns to its usual level and orders recover with it."}},{"id":"traffic","label":"Traffic","metric":"sessions","feed":"google-search","dropped":{"check":"Did fewer people arrive, and from which channel?","yes":"Sessions fall in one channel by about as much as orders do, while conversion holds."},"spiked":{"check":"Did a campaign, press mention or ranking change bring more visitors who buy?","yes":"Sessions rise in one channel and conversion holds; a bot wave would lift sessions but not orders."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did the share of visits that buy fall, and at which funnel step?","yes":"Conversion falls while traffic holds; one step explains most of it."},"spiked":{"check":"Did more visits buy, and at which funnel step?","yes":"Conversion rises while traffic holds; one step explains most of it."}},{"id":"first-orders","label":"First vs repeat orders","metric":"new-customers","breakdown":"is_first_order","dropped":{"check":"Did first orders fall, after an ad budget cut or a campaign ending, while repeat orders held?","yes":"New customers fall by about as much as orders."},"spiked":{"check":"Did an email, a launch or a restock bring back past customers?","yes":"Repeat orders jump while first orders hold."}}],"diagnose_order":["tracking","calendar","payments","traffic","conversion","first-orders"],"related":["net-revenue","aov","conversion-rate","sessions","new-customers"],"prose":{"why_it_matters":"Orders are the store's heartbeat, a count of decisions to buy, free of price and basket effects. Because they are a count, chance alone moves them by about 2.8 ÷ √N: a store with 800 orders a week swings ±10% on noise, while Northwind's 13,300 swing about ±2.5%.","pitfalls":["Count orders from the server or the payment processor, never from thank-you page views, which double count reloads and miss redirect payments.","Removing fully refunded orders rewrites past weeks for a month or more after they close. This spec counts orders when paid and reads refunds in refund rate.","Test orders, draft orders and $0 replacement orders inflate the count. Flag them at the source rather than filtering in every query.","Subscription renewals and marketplace orders follow their own calendars; mixed in with site orders, a renewal date looks like a sales spike."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "payment-success-rate": { yaml: "id: payment-success-rate\nname: Payment success rate\naliases:\n  - Payment authorization rate\n  - Authorization rate\n  - Payment approval rate\n  - Payment acceptance rate\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of payment attempts that succeed, across every gateway and payment method, in the week.\n  formula: Successful payment attempts ÷ all payment attempts (succeeded + failed)\n\nevents:\n  - name: payment_succeeded\n    description: A payment authorized and captured, from the processor's webhook, not the browser.\n    also_called: [payment_intent.succeeded, charge.succeeded, Payment Succeeded]\n    properties:\n      - name: gateway\n        description: The processor that handled it (stripe, adyen, paypal, shopify_payments).\n      - name: method\n        description: card, apple_pay, google_pay, paypal, klarna and so on.\n      - name: amount\n        description: The amount attempted.\n  - name: payment_failed\n    description: A payment attempt declined or errored, one event per attempt, from the processor's webhook.\n    also_called: [payment_intent.payment_failed, charge.failed, Payment Failed]\n    properties:\n      - name: gateway\n        description: The processor that handled it.\n      - name: method\n        description: The payment method attempted.\n      - name: decline_code\n        description: The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent.\n\nnumerator:\n  label: Successful payment attempts\n  aggregate: count\n  event: payment_succeeded\n\nqueries:\n  hogql: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(timestamp) AS week,\n      countIf(event = 'payment_succeeded') AS numerator,\n      count() AS denominator,\n      if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM events\n    WHERE event IN ('payment_succeeded', 'payment_failed')\n      AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n      AND timestamp < toStartOfWeek(now(), 1)\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    SELECT\n      date_trunc('week', occurred_at)::date AS week,\n      count(*) FILTER (WHERE event_name = 'payment_succeeded') AS numerator,\n      count(*) AS denominator,\n      (count(*) FILTER (WHERE event_name = 'payment_succeeded'))::numeric / nullif(count(*), 0) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n      AND occurred_at < date_trunc('week', now())\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    SELECT\n      DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n      COUNTIF(event_name = 'payment_succeeded') AS numerator,\n      COUNT(*) AS denominator,\n      SAFE_DIVIDE(COUNTIF(event_name = 'payment_succeeded'), COUNT(*)) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n      AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    SELECT\n      DATE_TRUNC('week', occurred_at)::date AS week,\n      COUNT_IF(event_name = 'payment_succeeded') AS numerator,\n      COUNT(*) AS denominator,\n      DIV0NULL(COUNT_IF(event_name = 'payment_succeeded'), COUNT(*)) AS value\n    FROM events\n    WHERE event_name IN ('payment_succeeded', 'payment_failed')\n      AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n      AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n    GROUP BY 1\n    ORDER BY 1;\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: payment attempts a week\n  typical: 0.92\n\nexample:\n  business: store\n  level: 0.93\n  volume: 14300\n  trend: 0\n\ndrivers:\n  - id: card-testing\n    label: Card testing and bots\n    dropped:\n      check: Is a card-testing attack sending bursts of failed attempts with stolen cards?\n      yes: Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold.\n    spiked:\n      check: Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?\n      yes: Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying.\n  - id: processor\n    label: Processor incidents\n    breakdown: gateway\n    feed: stripe\n    dropped:\n      check: Did one gateway or processor have an outage or a degraded period this week?\n      yes: Failures concentrate on one gateway during the hours of an incident on its status page.\n    spiked:\n      check: Did an incident from the week before clear?\n      yes: The affected gateway returns to its usual rate and the others never moved.\n  - id: method\n    label: Payment methods\n    breakdown: method\n    dropped:\n      check: Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?\n      yes: One method's success falls while cards and the other methods hold.\n    spiked:\n      check: Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?\n      yes: Each method's own rate holds and only the mix moved.\n  - id: fraud-rules\n    label: Fraud rules and 3-D Secure\n    breakdown: decline_code\n    dropped:\n      check: Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?\n      yes: One decline code, such as fraudulent or authentication_required, rises from the day the rule changed.\n    spiked:\n      check: Was a fraud rule loosened? Check disputes before celebrating.\n      yes: Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later.\n  - id: country-mix\n    label: Countries and card issuers\n    breakdown: $geoip_country_code\n    dropped:\n      check: Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?\n      yes: One country's share of attempts grows and its success rate sits well below the rest.\n    spiked:\n      check: Did a low-approval country shrink, or did a local payment method launch there?\n      yes: The country mix moved, or one country's rate rose from the day a method launched.\n\ndiagnose_order: [card-testing, processor, method, fraud-rules, country-mix]\n\nrelated: [checkout-conversion, conversion-rate, orders, mobile-conversion-rate, net-revenue]\n\nprose:\n  why_it_matters: >-\n    Every failed payment is a shopper who had already decided to buy and typed in a card. A fall\n    is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen\n    cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a\n    week, most of them from people standing at the till.\n  pitfalls:\n    - Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.\n    - Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.\n    - Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.\n    - Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"payment-success-rate","name":"Payment success rate","aliases":["Payment authorization rate","Authorization rate","Payment approval rate","Payment acceptance rate"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of payment attempts that succeed, across every gateway and payment method, in the week.","formula":"Successful payment attempts ÷ all payment attempts (succeeded + failed)"},"events":[{"name":"payment_succeeded","description":"A payment authorized and captured, from the processor's webhook, not the browser.","also_called":["payment_intent.succeeded","charge.succeeded","Payment Succeeded"],"properties":[{"name":"gateway","description":"The processor that handled it (stripe, adyen, paypal, shopify_payments)."},{"name":"method","description":"card, apple_pay, google_pay, paypal, klarna and so on."},{"name":"amount","description":"The amount attempted."}]},{"name":"payment_failed","description":"A payment attempt declined or errored, one event per attempt, from the processor's webhook.","also_called":["payment_intent.payment_failed","charge.failed","Payment Failed"],"properties":[{"name":"gateway","description":"The processor that handled it."},{"name":"method","description":"The payment method attempted."},{"name":"decline_code","description":"The issuer's or processor's reason, such as insufficient_funds, do_not_honor or fraudulent."}]}],"numerator":{"label":"Successful payment attempts","aggregate":"count","event":"payment_succeeded"},"queries":{"hogql":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(timestamp) AS week,\n  countIf(event = 'payment_succeeded') AS numerator,\n  count() AS denominator,\n  if(denominator > 0, numerator / denominator, NULL) AS value\nFROM events\nWHERE event IN ('payment_succeeded', 'payment_failed')\n  AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n  AND timestamp < toStartOfWeek(now(), 1)\nGROUP BY week\nORDER BY week","postgres":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nSELECT\n  date_trunc('week', occurred_at)::date AS week,\n  count(*) FILTER (WHERE event_name = 'payment_succeeded') AS numerator,\n  count(*) AS denominator,\n  (count(*) FILTER (WHERE event_name = 'payment_succeeded'))::numeric / nullif(count(*), 0) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n  AND occurred_at < date_trunc('week', now())\nGROUP BY 1\nORDER BY 1;","bigquery":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nSELECT\n  DATE_TRUNC(DATE(occurred_at), ISOWEEK) AS week,\n  COUNTIF(event_name = 'payment_succeeded') AS numerator,\n  COUNT(*) AS denominator,\n  SAFE_DIVIDE(COUNTIF(event_name = 'payment_succeeded'), COUNT(*)) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n  AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\nGROUP BY week\nORDER BY week;","snowflake":"-- Payment success rate: successful payment attempts ÷ all attempts. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nSELECT\n  DATE_TRUNC('week', occurred_at)::date AS week,\n  COUNT_IF(event_name = 'payment_succeeded') AS numerator,\n  COUNT(*) AS denominator,\n  DIV0NULL(COUNT_IF(event_name = 'payment_succeeded'), COUNT(*)) AS value\nFROM events\nWHERE event_name IN ('payment_succeeded', 'payment_failed')\n  AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n  AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\nGROUP BY 1\nORDER BY 1;"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"payment attempts a week","typical":0.92},"example":{"business":"store","level":0.93,"volume":14300,"trend":0},"drivers":[{"id":"card-testing","label":"Card testing and bots","dropped":{"check":"Is a card-testing attack sending bursts of failed attempts with stolen cards?","yes":"Failed attempts spike within hours from a few sessions or IPs, with small amounts and codes like incorrect_cvc, while orders hold."},"spiked":{"check":"Did a card-testing attack from last week stop, or did a new rule block bots before they reach the processor?","yes":"Failed attempts fall back while successful payments hold; the rise is a smaller denominator, not more customers paying."}},{"id":"processor","label":"Processor incidents","breakdown":"gateway","feed":"stripe","dropped":{"check":"Did one gateway or processor have an outage or a degraded period this week?","yes":"Failures concentrate on one gateway during the hours of an incident on its status page."},"spiked":{"check":"Did an incident from the week before clear?","yes":"The affected gateway returns to its usual rate and the others never moved."}},{"id":"method","label":"Payment methods","breakdown":"method","dropped":{"check":"Is one method failing, such as Apple Pay, PayPal, a buy-now-pay-later provider or 3-D Secure cards?","yes":"One method's success falls while cards and the other methods hold."},"spiked":{"check":"Did wallets, which approve more often than typed cards, gain share, or did a weak method get removed?","yes":"Each method's own rate holds and only the mix moved."}},{"id":"fraud-rules","label":"Fraud rules and 3-D Secure","breakdown":"decline_code","dropped":{"check":"Did a fraud rule, risk setting or 3-D Secure change start blocking good customers?","yes":"One decline code, such as fraudulent or authentication_required, rises from the day the rule changed."},"spiked":{"check":"Was a fraud rule loosened? Check disputes before celebrating.","yes":"Blocked attempts fall from the day of the change, and fraud disputes may rise a few weeks later."}},{"id":"country-mix","label":"Countries and card issuers","breakdown":"$geoip_country_code","dropped":{"check":"Did more attempts come from countries where cross-border cards decline more often, for example after a new campaign?","yes":"One country's share of attempts grows and its success rate sits well below the rest."},"spiked":{"check":"Did a low-approval country shrink, or did a local payment method launch there?","yes":"The country mix moved, or one country's rate rose from the day a method launched."}}],"diagnose_order":["card-testing","processor","method","fraud-rules","country-mix"],"related":["checkout-conversion","conversion-rate","orders","mobile-conversion-rate","net-revenue"],"prose":{"why_it_matters":"Every failed payment is a shopper who had already decided to buy and typed in a card. A fall is rarely about the shopper; it is a processor incident, a fraud rule or a bot testing stolen cards. At Northwind, with about 14,000 attempts a week, one point is 140 failed attempts a week, most of them from people standing at the till.","pitfalls":["Retries count as attempts, so a shopper who is declined twice and then pays is one success in three. Read checkout conversion beside it to see what shoppers experienced.","Card-testing bots can send thousands of failed attempts in an hour and pull a week down ten points with no real customer affected. Split by session or IP before reacting.","Record payment events from the processor's webhooks, not the browser. Browser events miss redirect methods such as PayPal and Klarna and duplicate on reloads.","Processors disagree on what a failure is; a 3-D Secure challenge the shopper abandons is a failure in some and nothing in others. Changing processors moves the rate with no change in approvals."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "product-view-rate": { yaml: "id: product-view-rate\nname: Product view rate\naliases:\n  - Product page view rate\n  - PDP view rate\n  - Product detail view rate\nfamily: conversion\ncatalog_id: product_view_rate\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that viewed at least one product page, the first step of the store funnel.\n  formula: Sessions with a product view ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: product_viewed\n    description: A product detail page rendered with its product, once per view.\n    also_called: [view_item, Product Viewed, product_viewed]\n    properties:\n      - name: product_id\n        description: The product shown.\n      - name: price\n        description: The price shown, before discounts.\n\nnumerator:\n  label: Sessions that viewed a product\n  aggregate: unique_sessions\n  event: product_viewed\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions a week\n  typical: 0.55\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 0.62\n  volume: 600000\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a theme, app or tag change stop product_viewed firing on some product templates?\n      yes: Page views on product URLs hold while product_viewed events fall, often on one template or device.\n    spiked:\n      check: Is product_viewed now firing on quick views, collection grids or twice per page?\n      yes: Product views per session jump, or the event appears on paths that are not product pages.\n  - id: bot-traffic\n    label: Bots and junk sessions\n    breakdown: $browser\n    dropped:\n      check: Did a wave of bot or junk sessions add visits that never reach a product?\n      yes: Sessions jump from one browser, country or referrer with one page per session and almost no product views.\n    spiked:\n      check: Did a bot source stop, shrinking the denominator rather than lifting real browsing?\n      yes: Sessions fall from one browser or country while sessions that viewed a product hold.\n  - id: traffic-mix\n    label: Landing channel\n    breakdown: utm_source\n    dropped:\n      check: Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?\n      yes: One source gains share of sessions and its product view rate sits far below the rest.\n    spiked:\n      check: Did campaigns start sending people straight to product pages, or did a low-intent source shrink?\n      yes: One source's share or view rate moves from the day a campaign or link changed.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, for example after a mobile menu or search change?\n      yes: Mobile falls several points while desktop is flat, starting on a release day.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device jumps after a release; confirm product_viewed didn't start firing twice there first.\n  - id: navigation\n    label: Homepage and navigation\n    dropped:\n      check: Did a homepage, menu, search or collection change make products harder to reach?\n      yes: Sessions that land on the changed page view fewer products from the day it shipped, on every channel.\n    spiked:\n      check: Did a homepage, menu or collection change put products one click closer?\n      yes: Sessions that land on the changed page view more products from the day it shipped, on every channel.\n\ndiagnose_order: [tracking, bot-traffic, traffic-mix, device-split, navigation]\n\nrelated: [sessions, bounce-rate, add-to-cart-rate, conversion-rate, pages-per-session]\n\nprose:\n  why_it_matters: >-\n    Product view rate says whether visitors find something worth a closer look, before price,\n    stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000\n    sessions that never see a product; at the 3.6% of product viewers who go on to order, that\n    is about 200 orders a week.\n  pitfalls:\n    - Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.\n    - Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.\n    - Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.\n    - Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"product-view-rate","name":"Product view rate","aliases":["Product page view rate","PDP view rate","Product detail view rate"],"family":"conversion","catalog_id":"product_view_rate","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that viewed at least one product page, the first step of the store funnel.","formula":"Sessions with a product view ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"product_viewed","description":"A product detail page rendered with its product, once per view.","also_called":["view_item","Product Viewed","product_viewed"],"properties":[{"name":"product_id","description":"The product shown."},{"name":"price","description":"The price shown, before discounts."}]}],"numerator":{"label":"Sessions that viewed a product","aggregate":"unique_sessions","event":"product_viewed"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions a week","typical":0.55,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":0.62,"volume":600000,"trend":0},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a theme, app or tag change stop product_viewed firing on some product templates?","yes":"Page views on product URLs hold while product_viewed events fall, often on one template or device."},"spiked":{"check":"Is product_viewed now firing on quick views, collection grids or twice per page?","yes":"Product views per session jump, or the event appears on paths that are not product pages."}},{"id":"bot-traffic","label":"Bots and junk sessions","breakdown":"$browser","dropped":{"check":"Did a wave of bot or junk sessions add visits that never reach a product?","yes":"Sessions jump from one browser, country or referrer with one page per session and almost no product views."},"spiked":{"check":"Did a bot source stop, shrinking the denominator rather than lifting real browsing?","yes":"Sessions fall from one browser or country while sessions that viewed a product hold."}},{"id":"traffic-mix","label":"Landing channel","breakdown":"utm_source","dropped":{"check":"Did a channel that rarely browses grow, such as a viral blog post, a giveaway or broad paid social?","yes":"One source gains share of sessions and its product view rate sits far below the rest."},"spiked":{"check":"Did campaigns start sending people straight to product pages, or did a low-intent source shrink?","yes":"One source's share or view rate moves from the day a campaign or link changed."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, for example after a mobile menu or search change?","yes":"Mobile falls several points while desktop is flat, starting on a release day."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device jumps after a release; confirm product_viewed didn't start firing twice there first."}},{"id":"navigation","label":"Homepage and navigation","dropped":{"check":"Did a homepage, menu, search or collection change make products harder to reach?","yes":"Sessions that land on the changed page view fewer products from the day it shipped, on every channel."},"spiked":{"check":"Did a homepage, menu or collection change put products one click closer?","yes":"Sessions that land on the changed page view more products from the day it shipped, on every channel."}}],"diagnose_order":["tracking","bot-traffic","traffic-mix","device-split","navigation"],"related":["sessions","bounce-rate","add-to-cart-rate","conversion-rate","pages-per-session"],"prose":{"why_it_matters":"Product view rate says whether visitors find something worth a closer look, before price, stock or checkout can matter. On a store with 600,000 sessions a week, one point is 6,000 sessions that never see a product; at the 3.6% of product viewers who go on to order, that is about 200 orders a week.","pitfalls":["Counting product views instead of sessions with a product view lets a few heavy browsers lift the rate. This spec counts each session once.","Decide whether quick-view pop-ups count as product views and keep that choice; switching it moves the rate several points with no change in shoppers.","Bot and crawler sessions land in the denominator only, so a bot wave reads as a fall in browsing. Split sessions by browser and country before acting.","Landing pages with their own buy button skip the product page, so the rate falls while sales hold. Fire product_viewed on those pages or read add-to-cart over all sessions instead."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "promo-code-usage-rate": { yaml: "id: promo-code-usage-rate\nname: Promo code usage rate\naliases:\n  - Coupon usage rate\n  - Discount code usage rate\n  - Coupon redemption rate\n  - Promo code redemption rate\nfamily: conversion\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: The share of paid orders placed with a discount code, the part of demand that only bought at a lower price.\n  formula: Paid orders with a discount code ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: coupon\n        description: The code redeemed on the order; absent when no code was used.\n      - name: discount\n        description: The total discount on the order, from codes and automatic offers.\n  - name: coupon_applied\n    description: A code entered at cart or checkout, valid or not.\n    also_called: [Coupon Entered, Coupon Applied, Coupon Denied]\n    properties:\n      - name: coupon\n        description: The code entered.\n      - name: valid\n        description: Whether the code was accepted.\n\nnumerator:\n  label: Orders with a code\n  aggregate: count\n  event: order_completed\n  where:\n    - property: coupon\n      op: is_set\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: binomial\n  min_denominator: 100\n  volume_unit: orders a week\n  typical: 0.25\n\nexample:\n  business: store\n  level: 0.24\n  volume: 13300\n  trend: 0.03\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a checkout migration or a new discount app stop sending the code on the order event?\n      yes: Discounts on orders hold while the coupon field goes blank from one day.\n    spiked:\n      check: Is the order event now sending an empty string or an automatic offer's name as the coupon?\n      yes: Orders with a coupon but no discount appear, or one code name shows up on most orders.\n  - id: campaigns\n    label: Sales and campaign codes\n    feed: shopping\n    dropped:\n      check: Did a sale end or a campaign code expire this week?\n      yes: One or two campaign codes that carried last week's orders fall away.\n    spiked:\n      check: Is a sale running on a code, or did an email or SMS send one this week?\n      yes: One or two campaign codes explain most of the rise, starting on the send or launch day.\n  - id: leaked-codes\n    label: Leaked codes\n    breakdown: coupon\n    dropped:\n      check: Did you disable a code that had leaked to coupon sites or browser extensions?\n      yes: That code's uses fall to zero and invalid attempts with it appear in coupon_applied.\n    spiked:\n      check: Did a code leak to a coupon site, a browser extension or a deal forum?\n      yes: One code's uses climb across channels it was never sent to, often on first orders.\n  - id: invalid-codes\n    label: Codes that fail\n    dropped:\n      check: Did codes start failing, from an expiry, a new minimum spend or a discount app error?\n      yes: coupon_applied with valid false rises, and checkout conversion may fall with it.\n    spiked:\n      check: Did the code field move up to the cart or become more visible, sending shoppers to look for codes?\n      yes: Uses of codes nobody sent this week rise from the day the field moved.\n  - id: partner-codes\n    label: Influencer and affiliate codes\n    breakdown: utm_source\n    dropped:\n      check: Did an influencer, affiliate or podcast campaign with its own code end?\n      yes: The partner's code and its traffic source fall away together.\n    spiked:\n      check: Did an influencer, affiliate or podcast campaign with its own code launch?\n      yes: The partner's code accounts for most of the rise, with orders from its source.\n  - id: new-customers\n    label: First orders and welcome codes\n    metric: new-customers\n    dropped:\n      check: Did fewer first-time customers arrive with a welcome code?\n      yes: Welcome code uses fall with new customers while repeat customers' code use holds.\n    spiked:\n      check: Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?\n      yes: Welcome code uses rise with new customers while repeat customers' code use holds.\n\ndiagnose_order: [tracking, campaigns, leaked-codes, invalid-codes, partner-codes, new-customers]\n\nrelated: [discount-rate, aov, checkout-conversion, new-customers, gross-margin]\n\nprose:\n  why_it_matters: >-\n    Every coded order is margin given away, and code usage creeps: a welcome code, an influencer\n    code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of\n    13,300 weekly orders use a code; five more points is about 650 more discounted orders a\n    week.\n  pitfalls:\n    - Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.\n    - Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.\n    - Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.\n    - Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"promo-code-usage-rate","name":"Promo code usage rate","aliases":["Coupon usage rate","Discount code usage rate","Coupon redemption rate","Promo code redemption rate"],"family":"conversion","kind":"rate","polarity":"down-is-good","definition":{"one_line":"The share of paid orders placed with a discount code, the part of demand that only bought at a lower price.","formula":"Paid orders with a discount code ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"coupon","description":"The code redeemed on the order; absent when no code was used."},{"name":"discount","description":"The total discount on the order, from codes and automatic offers."}]},{"name":"coupon_applied","description":"A code entered at cart or checkout, valid or not.","also_called":["Coupon Entered","Coupon Applied","Coupon Denied"],"properties":[{"name":"coupon","description":"The code entered."},{"name":"valid","description":"Whether the code was accepted."}]}],"numerator":{"label":"Orders with a code","aggregate":"count","event":"order_completed","where":[{"property":"coupon","op":"is_set"}]},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"binomial","min_denominator":100,"volume_unit":"orders a week","typical":0.25},"example":{"business":"store","level":0.24,"volume":13300,"trend":0.03,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a checkout migration or a new discount app stop sending the code on the order event?","yes":"Discounts on orders hold while the coupon field goes blank from one day."},"spiked":{"check":"Is the order event now sending an empty string or an automatic offer's name as the coupon?","yes":"Orders with a coupon but no discount appear, or one code name shows up on most orders."}},{"id":"campaigns","label":"Sales and campaign codes","feed":"shopping","dropped":{"check":"Did a sale end or a campaign code expire this week?","yes":"One or two campaign codes that carried last week's orders fall away."},"spiked":{"check":"Is a sale running on a code, or did an email or SMS send one this week?","yes":"One or two campaign codes explain most of the rise, starting on the send or launch day."}},{"id":"leaked-codes","label":"Leaked codes","breakdown":"coupon","dropped":{"check":"Did you disable a code that had leaked to coupon sites or browser extensions?","yes":"That code's uses fall to zero and invalid attempts with it appear in coupon_applied."},"spiked":{"check":"Did a code leak to a coupon site, a browser extension or a deal forum?","yes":"One code's uses climb across channels it was never sent to, often on first orders."}},{"id":"invalid-codes","label":"Codes that fail","dropped":{"check":"Did codes start failing, from an expiry, a new minimum spend or a discount app error?","yes":"coupon_applied with valid false rises, and checkout conversion may fall with it."},"spiked":{"check":"Did the code field move up to the cart or become more visible, sending shoppers to look for codes?","yes":"Uses of codes nobody sent this week rise from the day the field moved."}},{"id":"partner-codes","label":"Influencer and affiliate codes","breakdown":"utm_source","dropped":{"check":"Did an influencer, affiliate or podcast campaign with its own code end?","yes":"The partner's code and its traffic source fall away together."},"spiked":{"check":"Did an influencer, affiliate or podcast campaign with its own code launch?","yes":"The partner's code accounts for most of the rise, with orders from its source."}},{"id":"new-customers","label":"First orders and welcome codes","metric":"new-customers","dropped":{"check":"Did fewer first-time customers arrive with a welcome code?","yes":"Welcome code uses fall with new customers while repeat customers' code use holds."},"spiked":{"check":"Did more first-time customers arrive with a welcome code, from a pop-up change or an ad push?","yes":"Welcome code uses rise with new customers while repeat customers' code use holds."}}],"diagnose_order":["tracking","campaigns","leaked-codes","invalid-codes","partner-codes","new-customers"],"related":["discount-rate","aov","checkout-conversion","new-customers","gross-margin"],"prose":{"why_it_matters":"Every coded order is margin given away, and code usage creeps: a welcome code, an influencer code and a leaked code each add a few points that nobody decided on. At Northwind, 24% of 13,300 weekly orders use a code; five more points is about 650 more discounted orders a week.","pitfalls":["Automatic discounts and free-shipping rules leave the coupon empty, so a store that moves from codes to automatic offers sees code usage fall while it discounts more. Read discount rate beside it.","Send no coupon property when no code was used. An empty string counts as a code in most query engines, including this spec's test.","Welcome codes tie code usage to the new-customer mix, so a week with more first orders shows more codes without any change in promotions.","Browser coupon extensions try every code they know at checkout, so a code shared once can spread to a large share of orders within days. Watch the top code's share, not only the total."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "refund-rate": { yaml: "id: refund-rate\nname: Refund rate\naliases:\n  - Return rate\n  - Returns rate\n  - Refund percentage\nfamily: revenue\nkind: rate\npolarity: down-is-good\n\ndefinition:\n  one_line: Refunds issued this week as a share of this week's order revenue.\n  formula: Refunds issued ÷ order revenue after discounts, each by the week it happened\n\nevents:\n  - name: order_refunded\n    description: A refund issued against an earlier order, full or partial.\n    also_called: [refund, Order Refunded, charge.refunded]\n    properties:\n      - name: order_id\n        description: The order refunded; links the refund to the week it was sold.\n      - name: amount\n        description: The refunded amount, excluding tax and shipping.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Refunds issued\n  aggregate: sum\n  event: order_refunded\n  property: amount\ndenominator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\n\nnoise:\n  type: process\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 0.06\n\nexample:\n  business: store\n  level: 0.0335\n  volume: 13300\n  trend: 0\n\ndrivers:\n  - id: tracking\n    label: Tracking and processing\n    dropped:\n      check: Did refund events stop syncing, for example after a returns app or processor change?\n      yes: Refunds in the payment processor hold while recorded refunds fall.\n    spiked:\n      check: Did a backlog of refunds get processed in one batch, or are refunds recorded twice?\n      yes: Refunds cluster on one or two days, or the same order_id carries a partial and a full refund.\n  - id: past-sales\n    label: Last month's sales\n    feed: shopping\n    dropped:\n      check: Did a post-season wave of returns just end?\n      yes: Refunds fall back as the orders from the busy weeks pass their return window.\n    spiked:\n      check: Did a big sale or gifting season end two to six weeks ago?\n      yes: Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it.\n  - id: product-batch\n    label: One product or batch\n    dropped:\n      check: Did fixing a defect, a size chart or a product description cut returns on one product?\n      yes: Refunds on that product fall from the weeks after the fix.\n    spiked:\n      check: Is one product, size or batch behind most of the refunds?\n      yes: Return reasons cluster on one product, often defective, not as described or wrong size.\n  - id: delivery\n    label: Delivery problems\n    dropped:\n      check: Did a carrier or warehouse problem that caused refunds clear?\n      yes: Refunds for orders not received fall back to their usual level.\n    spiked:\n      check: Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?\n      yes: Refunds for orders not received rise in one region or with one carrier.\n  - id: fraud\n    label: Fraud and disputes\n    feed: stripe\n    dropped:\n      check: Did tighter fraud rules cut refunds issued to settle disputes?\n      yes: Refunds on first orders with high values or shared addresses fall.\n    spiked:\n      check: Did a fraud ring or a wave of disputes get settled with refunds?\n      yes: Refunds concentrate on first orders with high values, new cards or shared shipping addresses.\n  - id: policy\n    label: Return policy\n    dropped:\n      check: Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?\n      yes: Refunds fall from the policy date while exchanges rise.\n    spiked:\n      check: Did returns become free, the window lengthen, or a try-before-you-buy option launch?\n      yes: Refunds rise from the policy date, on orders placed after it.\n\ndiagnose_order: [tracking, past-sales, product-batch, delivery, fraud, policy]\n\nrelated: [net-revenue, orders, gross-margin, contribution-margin, gross-sales]\n\nprose:\n  why_it_matters: >-\n    Refunds are revenue the store already counted and then gave back, plus shipping both ways.\n    Because they follow sales by two to six weeks, the rate moves with last month's orders as\n    much as with today's quality. At Northwind, 3.5% of $1.33M of order revenue is about\n    $46,000 a week; one more point costs $13,300 a week before return shipping.\n  pitfalls:\n    - This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.\n    - Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.\n    - Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.\n    - Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"refund-rate","name":"Refund rate","aliases":["Return rate","Returns rate","Refund percentage"],"family":"revenue","kind":"rate","polarity":"down-is-good","definition":{"one_line":"Refunds issued this week as a share of this week's order revenue.","formula":"Refunds issued ÷ order revenue after discounts, each by the week it happened"},"events":[{"name":"order_refunded","description":"A refund issued against an earlier order, full or partial.","also_called":["refund","Order Refunded","charge.refunded"],"properties":[{"name":"order_id","description":"The order refunded; links the refund to the week it was sold."},{"name":"amount","description":"The refunded amount, excluding tax and shipping."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Refunds issued","aggregate":"sum","event":"order_refunded","property":"amount"},"denominator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"noise":{"type":"process","min_denominator":50,"volume_unit":"orders a week","typical":0.06},"example":{"business":"store","level":0.0335,"volume":13300,"trend":0},"drivers":[{"id":"tracking","label":"Tracking and processing","dropped":{"check":"Did refund events stop syncing, for example after a returns app or processor change?","yes":"Refunds in the payment processor hold while recorded refunds fall."},"spiked":{"check":"Did a backlog of refunds get processed in one batch, or are refunds recorded twice?","yes":"Refunds cluster on one or two days, or the same order_id carries a partial and a full refund."}},{"id":"past-sales","label":"Last month's sales","feed":"shopping","dropped":{"check":"Did a post-season wave of returns just end?","yes":"Refunds fall back as the orders from the busy weeks pass their return window."},"spiked":{"check":"Did a big sale or gifting season end two to six weeks ago?","yes":"Refunds rise in step with the orders of those weeks, not this week's, and the same weeks last year show it."}},{"id":"product-batch","label":"One product or batch","dropped":{"check":"Did fixing a defect, a size chart or a product description cut returns on one product?","yes":"Refunds on that product fall from the weeks after the fix."},"spiked":{"check":"Is one product, size or batch behind most of the refunds?","yes":"Return reasons cluster on one product, often defective, not as described or wrong size."}},{"id":"delivery","label":"Delivery problems","dropped":{"check":"Did a carrier or warehouse problem that caused refunds clear?","yes":"Refunds for orders not received fall back to their usual level."},"spiked":{"check":"Did a carrier delay, lost parcels or a warehouse error lead to refunds for orders not received?","yes":"Refunds for orders not received rise in one region or with one carrier."}},{"id":"fraud","label":"Fraud and disputes","feed":"stripe","dropped":{"check":"Did tighter fraud rules cut refunds issued to settle disputes?","yes":"Refunds on first orders with high values or shared addresses fall."},"spiked":{"check":"Did a fraud ring or a wave of disputes get settled with refunds?","yes":"Refunds concentrate on first orders with high values, new cards or shared shipping addresses."}},{"id":"policy","label":"Return policy","dropped":{"check":"Did the return window shorten, return shipping start costing, or exchanges get pushed over refunds?","yes":"Refunds fall from the policy date while exchanges rise."},"spiked":{"check":"Did returns become free, the window lengthen, or a try-before-you-buy option launch?","yes":"Refunds rise from the policy date, on orders placed after it."}}],"diagnose_order":["tracking","past-sales","product-batch","delivery","fraud","policy"],"related":["net-revenue","orders","gross-margin","contribution-margin","gross-sales"],"prose":{"why_it_matters":"Refunds are revenue the store already counted and then gave back, plus shipping both ways. Because they follow sales by two to six weeks, the rate moves with last month's orders as much as with today's quality. At Northwind, 3.5% of $1.33M of order revenue is about $46,000 a week; one more point costs $13,300 a week before return shipping.","pitfalls":["This spec divides refunds issued this week by this week's order revenue, so the rate rises for weeks after a big sale with no quality problem. For product quality, group refunds by the week of the original order instead.","Exchanges and store credit aren't refunds and don't appear here, so a store that pushes exchanges sees the rate fall while returns hold.","Partial refunds, price adjustments and goodwill credits count as refunds here. Tag them if you want returns alone.","Chargebacks run through a separate flow in most processors and appear here only if they are recorded as refunds."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "revenue-per-session": { yaml: "id: revenue-per-session\nname: Revenue per session\naliases:\n  - Revenue per visit\n  - RPS\n  - Revenue per visitor\n  - RPV\n  - Session value\nfamily: revenue\nkind: currency\npolarity: up-is-good\n\ndefinition:\n  one_line: Order revenue earned per session, the one number that combines conversion rate and order value.\n  formula: Order revenue after discounts ÷ sessions\n\nevents:\n  - name: $pageview\n    description: A page loaded in the browser. Sessions are the distinct session ids across page views.\n    also_called: [page_view, Page Viewed, page_viewed]\n    properties:\n      - name: $session_id\n        description: The browser session; a new one starts after 30 minutes without activity.\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: total\n        description: Order value after discounts, before tax and shipping.\n\nnumerator:\n  label: Order revenue\n  aggregate: sum\n  event: order_completed\n  property: total\ndenominator:\n  label: Sessions\n  aggregate: unique_sessions\n  event: $pageview\n\nnoise:\n  type: mean\n  cv: 9\n  min_denominator: 2000\n  volume_unit: sessions a week\n  typical: 2\n  reference_volumes: [2000, 10000, 50000, 250000]\n\nexample:\n  business: store\n  level: 2.22\n  volume: 600000\n  trend: 0.1\n  season: 1\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did orders stop recording, or did a new tag start splitting visits into extra sessions?\n      yes: Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day.\n    spiked:\n      check: Did page views stop recording on some pages or browsers, or did orders start recording twice?\n      yes: Sessions fall with no matching fall in ad clicks, or the same order_id appears twice.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a sale, holiday or payday week?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a sale, holiday or payday week?\n      yes: The same week last year shows the same jump once aligned on the event.\n  - id: traffic-mix\n    label: Who arrived\n    breakdown: utm_source\n    dropped:\n      check: Did sessions grow from a low-intent source or from bots?\n      yes: Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves.\n    spiked:\n      check: Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?\n      yes: Sessions fall while revenue holds. Check total revenue before celebrating.\n  - id: conversion\n    label: Store conversion\n    metric: conversion-rate\n    dropped:\n      check: Did a smaller share of sessions buy?\n      yes: Conversion falls by about as much as revenue per session while order value holds.\n    spiked:\n      check: Did a larger share of sessions buy?\n      yes: Conversion rises by about as much as revenue per session while order value holds.\n  - id: order-value\n    label: Order value\n    metric: aov\n    dropped:\n      check: Did orders get smaller, from discounts, fewer items or cheaper products?\n      yes: Order value falls while conversion holds.\n    spiked:\n      check: Did orders get larger, or did a handful of very large orders land?\n      yes: Order value rises while conversion holds; check the largest orders first.\n  - id: device-split\n    label: Mobile vs desktop\n    breakdown: $device_type\n    dropped:\n      check: Is the drop on one device type only, or did mobile take a larger share of sessions?\n      yes: One device falls while the other holds, or each holds and only the mix moved.\n    spiked:\n      check: Is the rise on one device type only?\n      yes: One device rises after a release; confirm it isn't a tracking change before crediting it.\n\ndiagnose_order: [tracking, calendar, traffic-mix, conversion, order-value, device-split]\n\nrelated: [conversion-rate, aov, sessions, net-revenue, cpc]\n\nprose:\n  why_it_matters: >-\n    Revenue per session is what a visit is worth, so it is the number to set beside what a visit\n    costs. At Northwind a session earns about $2.22; a channel that pays more than that times\n    gross margin, about $1.29, per session loses money on the first order. Because it multiplies\n    conversion by order value, it is also the fairest single number for tests that trade one\n    against the other.\n  pitfalls:\n    - Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.\n    - Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.\n    - Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.\n    - This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"revenue-per-session","name":"Revenue per session","aliases":["Revenue per visit","RPS","Revenue per visitor","RPV","Session value"],"family":"revenue","kind":"currency","polarity":"up-is-good","definition":{"one_line":"Order revenue earned per session, the one number that combines conversion rate and order value.","formula":"Order revenue after discounts ÷ sessions"},"events":[{"name":"$pageview","description":"A page loaded in the browser. Sessions are the distinct session ids across page views.","also_called":["page_view","Page Viewed","page_viewed"],"properties":[{"name":"$session_id","description":"The browser session; a new one starts after 30 minutes without activity."}]},{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"total","description":"Order value after discounts, before tax and shipping."}]}],"numerator":{"label":"Order revenue","aggregate":"sum","event":"order_completed","property":"total"},"denominator":{"label":"Sessions","aggregate":"unique_sessions","event":"$pageview"},"noise":{"type":"mean","cv":9,"min_denominator":2000,"volume_unit":"sessions a week","typical":2,"reference_volumes":[2000,10000,50000,250000]},"example":{"business":"store","level":2.22,"volume":600000,"trend":0.1,"season":1},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did orders stop recording, or did a new tag start splitting visits into extra sessions?","yes":"Orders in the store platform hold while recorded orders fall, or sessions per visitor jump on one day."},"spiked":{"check":"Did page views stop recording on some pages or browsers, or did orders start recording twice?","yes":"Sessions fall with no matching fall in ad clicks, or the same order_id appears twice."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a sale, holiday or payday week?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a sale, holiday or payday week?","yes":"The same week last year shows the same jump once aligned on the event."}},{"id":"traffic-mix","label":"Who arrived","breakdown":"utm_source","dropped":{"check":"Did sessions grow from a low-intent source or from bots?","yes":"Sessions jump from one source that earns a fraction of the rest per visit, while revenue barely moves."},"spiked":{"check":"Did a low-intent source or a bot wave shrink, lifting revenue per session without more revenue?","yes":"Sessions fall while revenue holds. Check total revenue before celebrating."}},{"id":"conversion","label":"Store conversion","metric":"conversion-rate","dropped":{"check":"Did a smaller share of sessions buy?","yes":"Conversion falls by about as much as revenue per session while order value holds."},"spiked":{"check":"Did a larger share of sessions buy?","yes":"Conversion rises by about as much as revenue per session while order value holds."}},{"id":"order-value","label":"Order value","metric":"aov","dropped":{"check":"Did orders get smaller, from discounts, fewer items or cheaper products?","yes":"Order value falls while conversion holds."},"spiked":{"check":"Did orders get larger, or did a handful of very large orders land?","yes":"Order value rises while conversion holds; check the largest orders first."}},{"id":"device-split","label":"Mobile vs desktop","breakdown":"$device_type","dropped":{"check":"Is the drop on one device type only, or did mobile take a larger share of sessions?","yes":"One device falls while the other holds, or each holds and only the mix moved."},"spiked":{"check":"Is the rise on one device type only?","yes":"One device rises after a release; confirm it isn't a tracking change before crediting it."}}],"diagnose_order":["tracking","calendar","traffic-mix","conversion","order-value","device-split"],"related":["conversion-rate","aov","sessions","net-revenue","cpc"],"prose":{"why_it_matters":"Revenue per session is what a visit is worth, so it is the number to set beside what a visit costs. At Northwind a session earns about $2.22; a channel that pays more than that times gross margin, about $1.29, per session loses money on the first order. Because it multiplies conversion by order value, it is also the fairest single number for tests that trade one against the other.","pitfalls":["Most sessions earn nothing and a few earn a lot, so the weekly figure swings with a handful of large orders. Below about 50,000 sessions a week, a 10% move is often chance.","Revenue per visitor divides by people, not sessions, and reads higher because visitors make several sessions. Don't compare one with the other's benchmark.","Bot sessions lower it without any change in shoppers. When it drops with revenue flat, check sessions by browser and country.","This spec uses order revenue before refunds so it matches what the sessions produced. Subtracting refunds makes it move with returns from earlier weeks."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "search-conversion-rate": { yaml: "id: search-conversion-rate\nname: Search conversion rate\naliases:\n  - Site search conversion rate\n  - Search to purchase rate\n  - Search conversion\nfamily: conversion\nkind: rate\npolarity: up-is-good\n\ndefinition:\n  one_line: The share of sessions that used site search and then placed a paid order in the same session.\n  formula: Sessions that searched, then ordered ÷ sessions that searched\n\nevents:\n  - name: product_searched\n    description: A search submitted in the store's search box, or its results page shown, once per search.\n    also_called: [search, view_search_results, Products Searched, search_submitted]\n    properties:\n      - name: query\n        description: What the shopper typed, as submitted.\n      - name: results_count\n        description: How many products the search returned; 0 is a dead end.\n  - name: order_completed\n    description: A paid order confirmed by the server, carrying the browser's session id.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n\nnumerator:\n  label: Sessions that searched, then ordered\n  aggregate: unique_sessions\n  event: order_completed\ndenominator:\n  label: Sessions that searched\n  aggregate: unique_sessions\n  event: product_searched\n\nqueries:\n  hogql: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    SELECT\n      toMonday(searched_at) AS week,\n      countIf(ordered_at >= searched_at) AS numerator,\n      count() AS denominator,\n      if(denominator > 0, numerator / denominator, NULL) AS value\n    FROM (\n      SELECT\n        $session_id AS session_id,\n        minIf(timestamp, event = 'product_searched') AS searched_at,\n        maxIf(timestamp, event = 'order_completed') AS ordered_at\n      FROM events\n      WHERE event IN ('product_searched', 'order_completed')\n        AND $session_id != ''\n        AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n        AND timestamp < toStartOfWeek(now(), 1)\n      GROUP BY session_id\n      HAVING countIf(event = 'product_searched') > 0\n    )\n    GROUP BY week\n    ORDER BY week\n  postgres: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH searches AS (\n      SELECT\n        session_id,\n        min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n        max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n        AND occurred_at < date_trunc('week', now())\n      GROUP BY session_id\n    )\n    SELECT\n      date_trunc('week', searched_at)::date AS week,\n      count(*) FILTER (WHERE ordered_at >= searched_at) AS numerator,\n      count(*) AS denominator,\n      (count(*) FILTER (WHERE ordered_at >= searched_at))::numeric / nullif(count(*), 0) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY 1\n    ORDER BY 1;\n  bigquery: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\n    WITH searches AS (\n      SELECT\n        session_id,\n        MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n        AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n      GROUP BY session_id\n    )\n    SELECT\n      DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n      COUNTIF(ordered_at >= searched_at) AS numerator,\n      COUNT(*) AS denominator,\n      SAFE_DIVIDE(COUNTIF(ordered_at >= searched_at), COUNT(*)) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY week\n    ORDER BY week;\n  snowflake: |-\n    -- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n    -- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\n    WITH searches AS (\n      SELECT\n        session_id,\n        MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n        MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n      FROM events\n      WHERE event_name IN ('product_searched', 'order_completed')\n        AND session_id IS NOT NULL\n        AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n        AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n      GROUP BY session_id\n    )\n    SELECT\n      DATE_TRUNC('week', searched_at)::date AS week,\n      COUNT_IF(ordered_at >= searched_at) AS numerator,\n      COUNT(*) AS denominator,\n      DIV0NULL(COUNT_IF(ordered_at >= searched_at), COUNT(*)) AS value\n    FROM searches\n    WHERE searched_at IS NOT NULL\n    GROUP BY 1\n    ORDER BY 1;\n\nnoise:\n  type: binomial\n  min_denominator: 500\n  volume_unit: sessions with a search a week\n  typical: 0.05\n  reference_volumes: [500, 2000, 10000, 50000]\n\nexample:\n  business: store\n  level: 0.052\n  volume: 66000\n  trend: 0.03\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did a search app or theme change start firing product_searched on autocomplete keystrokes?\n      yes: Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it.\n    spiked:\n      check: Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?\n      yes: Sessions with a search fall on one device or template while search orders hold.\n  - id: store-wide\n    label: The whole store\n    metric: conversion-rate\n    dropped:\n      check: Did conversion fall for everyone, not only for searchers?\n      yes: Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search.\n    spiked:\n      check: Did conversion rise for everyone, from a sale or a fix elsewhere?\n      yes: Search conversion and store conversion rise together, so search itself didn't change.\n  - id: zero-results\n    label: Searches with no results\n    dropped:\n      check: Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?\n      yes: The share of searches with results_count of 0 rises, concentrated in a few queries.\n    spiked:\n      check: Did a synonym, spelling or catalogue fix cut dead-end searches?\n      yes: Zero-result searches fall from the day of the fix, on the queries it covered.\n  - id: stock\n    label: Stock of searched products\n    dropped:\n      check: Are the products people search for most out of stock or missing common sizes?\n      yes: Top queries still return results, but their first results are sold out.\n    spiked:\n      check: Did a much-searched product come back in stock or launch?\n      yes: Orders after searching for that product's name jump from the restock or launch day.\n  - id: relevance\n    label: Ranking and relevance\n    dropped:\n      check: Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?\n      yes: Clicks on the first results fall for the top queries from the day of the change.\n    spiked:\n      check: Did a relevance change or test ship, and is it on for everyone?\n      yes: The rise starts on the release day across devices and queries.\n  - id: who-searches\n    label: Who searches\n    breakdown: $device_type\n    dropped:\n      check: Did the search box become more prominent, so more casual browsers search?\n      yes: Sessions with a search grow faster than orders after searching; search-driven orders still rise.\n    spiked:\n      check: Did the search box move or shrink, leaving fewer but more committed searchers?\n      yes: Sessions with a search fall while orders after searching hold.\n\ndiagnose_order: [tracking, store-wide, zero-results, stock, relevance, who-searches]\n\nrelated: [conversion-rate, product-view-rate, add-to-cart-rate, revenue-per-session]\n\nprose:\n  why_it_matters: >-\n    Shoppers who search say what they want in their own words, and they convert at roughly\n    twice the store average; at Northwind, 5.2% against 2.2%. A fall here is usually something\n    the team controls, such as a search app update, lost synonyms or empty results for the\n    words people actually type.\n  pitfalls:\n    - Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.\n    - Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.\n    - This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.\n    - Zero-result searches are the fastest thing to check. A rise in dead-end searches nearly always comes before a fall in search conversion.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"search-conversion-rate","name":"Search conversion rate","aliases":["Site search conversion rate","Search to purchase rate","Search conversion"],"family":"conversion","kind":"rate","polarity":"up-is-good","definition":{"one_line":"The share of sessions that used site search and then placed a paid order in the same session.","formula":"Sessions that searched, then ordered ÷ sessions that searched"},"events":[{"name":"product_searched","description":"A search submitted in the store's search box, or its results page shown, once per search.","also_called":["search","view_search_results","Products Searched","search_submitted"],"properties":[{"name":"query","description":"What the shopper typed, as submitted."},{"name":"results_count","description":"How many products the search returned; 0 is a dead end."}]},{"name":"order_completed","description":"A paid order confirmed by the server, carrying the browser's session id.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."}]}],"numerator":{"label":"Sessions that searched, then ordered","aggregate":"unique_sessions","event":"order_completed"},"denominator":{"label":"Sessions that searched","aggregate":"unique_sessions","event":"product_searched"},"queries":{"hogql":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\nSELECT\n  toMonday(searched_at) AS week,\n  countIf(ordered_at >= searched_at) AS numerator,\n  count() AS denominator,\n  if(denominator > 0, numerator / denominator, NULL) AS value\nFROM (\n  SELECT\n    $session_id AS session_id,\n    minIf(timestamp, event = 'product_searched') AS searched_at,\n    maxIf(timestamp, event = 'order_completed') AS ordered_at\n  FROM events\n  WHERE event IN ('product_searched', 'order_completed')\n    AND $session_id != ''\n    AND timestamp >= toStartOfWeek(now(), 1) - toIntervalWeek(26)\n    AND timestamp < toStartOfWeek(now(), 1)\n  GROUP BY session_id\n  HAVING countIf(event = 'product_searched') > 0\n)\nGROUP BY week\nORDER BY week","postgres":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- Postgres. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH searches AS (\n  SELECT\n    session_id,\n    min(occurred_at) FILTER (WHERE event_name = 'product_searched') AS searched_at,\n    max(occurred_at) FILTER (WHERE event_name = 'order_completed') AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= date_trunc('week', now()) - interval '26 weeks'\n    AND occurred_at < date_trunc('week', now())\n  GROUP BY session_id\n)\nSELECT\n  date_trunc('week', searched_at)::date AS week,\n  count(*) FILTER (WHERE ordered_at >= searched_at) AS numerator,\n  count(*) AS denominator,\n  (count(*) FILTER (WHERE ordered_at >= searched_at))::numeric / nullif(count(*), 0) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY 1\nORDER BY 1;","bigquery":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- BigQuery. Assumes events(event_name, occurred_at, user_id, session_id, properties): one row per event, occurred_at in UTC, properties as JSON.\nWITH searches AS (\n  SELECT\n    session_id,\n    MIN(IF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= TIMESTAMP(DATE_SUB(DATE_TRUNC(CURRENT_DATE(), ISOWEEK), INTERVAL 26 WEEK))\n    AND occurred_at < TIMESTAMP(DATE_TRUNC(CURRENT_DATE(), ISOWEEK))\n  GROUP BY session_id\n)\nSELECT\n  DATE_TRUNC(DATE(searched_at), ISOWEEK) AS week,\n  COUNTIF(ordered_at >= searched_at) AS numerator,\n  COUNT(*) AS denominator,\n  SAFE_DIVIDE(COUNTIF(ordered_at >= searched_at), COUNT(*)) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY week\nORDER BY week;","snowflake":"-- Search conversion rate: sessions that searched, then placed a paid order ÷ sessions that searched. One row per complete week, last 26 weeks.\n-- Snowflake. Assumes WEEK_START = 1 (Monday) and events(event_name, occurred_at, user_id, session_id, properties), occurred_at in UTC.\nWITH searches AS (\n  SELECT\n    session_id,\n    MIN(IFF(event_name = 'product_searched', occurred_at, NULL)) AS searched_at,\n    MAX(IFF(event_name = 'order_completed', occurred_at, NULL)) AS ordered_at\n  FROM events\n  WHERE event_name IN ('product_searched', 'order_completed')\n    AND session_id IS NOT NULL\n    AND occurred_at >= DATEADD(week, -26, DATE_TRUNC('week', CURRENT_DATE()))\n    AND occurred_at < DATE_TRUNC('week', CURRENT_DATE())\n  GROUP BY session_id\n)\nSELECT\n  DATE_TRUNC('week', searched_at)::date AS week,\n  COUNT_IF(ordered_at >= searched_at) AS numerator,\n  COUNT(*) AS denominator,\n  DIV0NULL(COUNT_IF(ordered_at >= searched_at), COUNT(*)) AS value\nFROM searches\nWHERE searched_at IS NOT NULL\nGROUP BY 1\nORDER BY 1;"},"noise":{"type":"binomial","min_denominator":500,"volume_unit":"sessions with a search a week","typical":0.05,"reference_volumes":[500,2000,10000,50000]},"example":{"business":"store","level":0.052,"volume":66000,"trend":0.03},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did a search app or theme change start firing product_searched on autocomplete keystrokes?","yes":"Sessions with a search jump on the release day, many with a one- or two-letter query and nothing after it."},"spiked":{"check":"Did product_searched stop firing on some pages or devices, leaving only the most determined searchers?","yes":"Sessions with a search fall on one device or template while search orders hold."}},{"id":"store-wide","label":"The whole store","metric":"conversion-rate","dropped":{"check":"Did conversion fall for everyone, not only for searchers?","yes":"Search conversion and store conversion fall together, so the cause is checkout, price or the calendar, not search."},"spiked":{"check":"Did conversion rise for everyone, from a sale or a fix elsewhere?","yes":"Search conversion and store conversion rise together, so search itself didn't change."}},{"id":"zero-results","label":"Searches with no results","dropped":{"check":"Did more searches return nothing, from a catalogue change, lost synonyms or a trending term you don't stock?","yes":"The share of searches with results_count of 0 rises, concentrated in a few queries."},"spiked":{"check":"Did a synonym, spelling or catalogue fix cut dead-end searches?","yes":"Zero-result searches fall from the day of the fix, on the queries it covered."}},{"id":"stock","label":"Stock of searched products","dropped":{"check":"Are the products people search for most out of stock or missing common sizes?","yes":"Top queries still return results, but their first results are sold out."},"spiked":{"check":"Did a much-searched product come back in stock or launch?","yes":"Orders after searching for that product's name jump from the restock or launch day."}},{"id":"relevance","label":"Ranking and relevance","dropped":{"check":"Did a search app update, re-index or merchandising rule push irrelevant or sold-out products to the top?","yes":"Clicks on the first results fall for the top queries from the day of the change."},"spiked":{"check":"Did a relevance change or test ship, and is it on for everyone?","yes":"The rise starts on the release day across devices and queries."}},{"id":"who-searches","label":"Who searches","breakdown":"$device_type","dropped":{"check":"Did the search box become more prominent, so more casual browsers search?","yes":"Sessions with a search grow faster than orders after searching; search-driven orders still rise."},"spiked":{"check":"Did the search box move or shrink, leaving fewer but more committed searchers?","yes":"Sessions with a search fall while orders after searching hold."}}],"diagnose_order":["tracking","store-wide","zero-results","stock","relevance","who-searches"],"related":["conversion-rate","product-view-rate","add-to-cart-rate","revenue-per-session"],"prose":{"why_it_matters":"Shoppers who search say what they want in their own words, and they convert at roughly twice the store average; at Northwind, 5.2% against 2.2%. A fall here is usually something the team controls, such as a search app update, lost synonyms or empty results for the words people actually type.","pitfalls":["Searchers are more committed than average, so a high search conversion doesn't prove search works. Compare search conversion with itself over time, not with the store rate.","Predictive search that fires the event on each keystroke counts sessions that never submitted a search. Fire product_searched on submit or on the results view.","This spec credits search only when the order follows in the same session. A shopper who searches today and buys tomorrow counts as a search that didn't convert.","Zero-result searches are the fastest thing to check. A rise in dead-end searches nearly always comes before a fall in search conversion."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
  "units-per-order": { yaml: "id: units-per-order\nname: Units per order\naliases:\n  - Units per transaction\n  - UPT\n  - Items per order\n  - Average basket size\n  - Basket size\nfamily: revenue\nkind: ratio\npolarity: up-is-good\n\ndefinition:\n  one_line: The average number of items in a paid order, the basket half of average order value.\n  formula: Items sold ÷ paid orders\n\nevents:\n  - name: order_completed\n    description: A paid order confirmed by the server, not the thank-you page view.\n    also_called: [purchase, Order Completed, checkout_completed]\n    properties:\n      - name: item_count\n        description: Total units in the order, summing each line's quantity.\n      - name: order_id\n        description: Unique per order; deduplicates retries and reloads.\n      - name: is_first_order\n        description: True when it is the customer's first ever paid order.\n\nnumerator:\n  label: Items sold\n  aggregate: sum\n  event: order_completed\n  property: item_count\ndenominator:\n  label: Paid orders\n  aggregate: count\n  event: order_completed\n\nnoise:\n  type: mean\n  cv: 0.75\n  min_denominator: 50\n  volume_unit: orders a week\n  typical: 1.8\n\nexample:\n  business: store\n  level: 1.86\n  volume: 13300\n  trend: 0.05\n\ndrivers:\n  - id: tracking\n    label: Tracking change\n    dropped:\n      check: Did item_count switch from units to line items, or stop counting bundle components?\n      yes: Units per order step down on one release day while order value holds.\n    spiked:\n      check: Did item_count start counting free gifts, samples or shipping protection as items?\n      yes: Units step up on one day, and orders carry $0 lines they didn't before.\n  - id: calendar\n    label: Shopping calendar\n    feed: shopping\n    dropped:\n      check: Was last week a gifting or stock-up week, when baskets run larger?\n      yes: The same week last year shows the same dip once aligned on the event.\n    spiked:\n      check: Is this a gifting or stock-up week?\n      yes: The same week last year shows the same rise once aligned on the event.\n  - id: offers\n    label: Bundles and thresholds\n    dropped:\n      check: Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?\n      yes: The share of one-item orders rises from the day the offer changed.\n    spiked:\n      check: Did a buy-two offer, a bundle or a higher free-shipping threshold go live?\n      yes: The share of one-item orders falls from the launch day.\n  - id: cross-sell\n    label: Cart recommendations\n    dropped:\n      check: Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?\n      yes: Adds from recommendations fall to near zero from one day.\n    spiked:\n      check: Did a new cross-sell launch, and are its adds paid items rather than free gifts?\n      yes: Adds from recommendations rise and the extra items carry a price.\n  - id: product-mix\n    label: Product mix\n    dropped:\n      check: Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?\n      yes: Orders for that product grow while other baskets hold their size.\n    spiked:\n      check: Did consumables, refills or small accessories that people buy several of gain share?\n      yes: Orders containing those products grow while other baskets hold their size.\n  - id: first-orders\n    label: First vs repeat orders\n    breakdown: is_first_order\n    dropped:\n      check: Did first orders, which tend to hold fewer items, take a larger share?\n      yes: Each group's average holds and only the mix moved.\n    spiked:\n      check: Did repeat customers, who know what they want, take a larger share?\n      yes: The mix moved toward repeat orders while each group's average held.\n\ndiagnose_order: [tracking, calendar, offers, cross-sell, product-mix, first-orders]\n\nrelated: [aov, gross-sales, orders, discount-rate, add-to-cart-rate]\n\nprose:\n  why_it_matters: >-\n    Units per order is the basket half of average order value; AOV is units per order × the\n    average price per unit. Bundles, free-shipping thresholds and cross-sells act on it\n    directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new\n    customers.\n  pitfalls:\n    - Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.\n    - Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.\n    - A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.\n    - An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders.\n\nreviewed_by: null\nreviewed_at: null\nversion: 1\n", data: {"id":"units-per-order","name":"Units per order","aliases":["Units per transaction","UPT","Items per order","Average basket size","Basket size"],"family":"revenue","kind":"ratio","polarity":"up-is-good","definition":{"one_line":"The average number of items in a paid order, the basket half of average order value.","formula":"Items sold ÷ paid orders"},"events":[{"name":"order_completed","description":"A paid order confirmed by the server, not the thank-you page view.","also_called":["purchase","Order Completed","checkout_completed"],"properties":[{"name":"item_count","description":"Total units in the order, summing each line's quantity."},{"name":"order_id","description":"Unique per order; deduplicates retries and reloads."},{"name":"is_first_order","description":"True when it is the customer's first ever paid order."}]}],"numerator":{"label":"Items sold","aggregate":"sum","event":"order_completed","property":"item_count"},"denominator":{"label":"Paid orders","aggregate":"count","event":"order_completed"},"noise":{"type":"mean","cv":0.75,"min_denominator":50,"volume_unit":"orders a week","typical":1.8},"example":{"business":"store","level":1.86,"volume":13300,"trend":0.05},"drivers":[{"id":"tracking","label":"Tracking change","dropped":{"check":"Did item_count switch from units to line items, or stop counting bundle components?","yes":"Units per order step down on one release day while order value holds."},"spiked":{"check":"Did item_count start counting free gifts, samples or shipping protection as items?","yes":"Units step up on one day, and orders carry $0 lines they didn't before."}},{"id":"calendar","label":"Shopping calendar","feed":"shopping","dropped":{"check":"Was last week a gifting or stock-up week, when baskets run larger?","yes":"The same week last year shows the same dip once aligned on the event."},"spiked":{"check":"Is this a gifting or stock-up week?","yes":"The same week last year shows the same rise once aligned on the event."}},{"id":"offers","label":"Bundles and thresholds","dropped":{"check":"Did a bundle, a multi-buy offer or a free-shipping threshold end or fall?","yes":"The share of one-item orders rises from the day the offer changed."},"spiked":{"check":"Did a buy-two offer, a bundle or a higher free-shipping threshold go live?","yes":"The share of one-item orders falls from the launch day."}},{"id":"cross-sell","label":"Cart recommendations","dropped":{"check":"Did a cart upsell, recommendations widget or frequently-bought-together block break or get removed?","yes":"Adds from recommendations fall to near zero from one day."},"spiked":{"check":"Did a new cross-sell launch, and are its adds paid items rather than free gifts?","yes":"Adds from recommendations rise and the extra items carry a price."}},{"id":"product-mix","label":"Product mix","dropped":{"check":"Did a single-item product, such as a high-priced hero or a new launch, take a larger share of orders?","yes":"Orders for that product grow while other baskets hold their size."},"spiked":{"check":"Did consumables, refills or small accessories that people buy several of gain share?","yes":"Orders containing those products grow while other baskets hold their size."}},{"id":"first-orders","label":"First vs repeat orders","breakdown":"is_first_order","dropped":{"check":"Did first orders, which tend to hold fewer items, take a larger share?","yes":"Each group's average holds and only the mix moved."},"spiked":{"check":"Did repeat customers, who know what they want, take a larger share?","yes":"The mix moved toward repeat orders while each group's average held."}}],"diagnose_order":["tracking","calendar","offers","cross-sell","product-mix","first-orders"],"related":["aov","gross-sales","orders","discount-rate","add-to-cart-rate"],"prose":{"why_it_matters":"Units per order is the basket half of average order value; AOV is units per order × the average price per unit. Bundles, free-shipping thresholds and cross-sells act on it directly. Going from 1.8 to 1.9 at Northwind is about 1,330 more items a week with no new customers.","pitfalls":["Decide whether item_count counts units or line items and keep it; switching changes every multi-quantity order.","Free gifts, samples and shipping protection count as items unless excluded, so a gift-with-purchase lifts units with no extra sales.","A bundle sold as one product counts as one item. Splitting a bundle into its parts in the catalogue changes units per order without changing what shoppers bought.","An average hides the shape. A move from 1.8 to 1.9 usually means fewer one-item orders, not bigger baskets everywhere; check the share of one-item orders."]},"reviewed_by":null,"reviewed_at":null,"version":1} },
}
